INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('20-em-1-brazil', 'Master System', '20 em 1 (Brazil)', '1995', 'Compilation', 'Sega', '1', 'Various', 'Variety of mini-games and arcade ports.', 'Complete various challenges across 20 titles.', 'A multi-game cartridge featuring 20 diverse titles.', 'Experience a massive collection of 20 classic titles in one. This Brazilian exclusive compilation offers everything from puzzles to action, providing hours of retro gaming variety for the Sega Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-of-aces-europe', 'Master System', 'Ace of Aces (Europe)', '1986', 'Shooter', 'Artech Studios', '1', 'Arcade', 'Flight simulation and aerial combat.', 'Complete strategic bombing and intercept missions.', 'A realistic WWII flight simulator and combat game.', 'Take to the skies in Ace of Aces, the definitive WWII flight simulation for Master System. Manage your cockpit instruments and engage in dogfights as you complete high-stakes missions behind enemy lines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('action-fighter-japan-europe-v11', 'Master System', 'Action Fighter (Japan, Europe) (v1.1)', '1986', 'Shooter', 'Sega', '1', 'Arcade', 'Transformation-based vehicular combat.', 'Infiltrate enemy bases by land and air.', 'High-speed vehicle action that transforms from bike to jet.', 'Action Fighter delivers intense arcade-style combat. Upgrade your vehicle from a motorcycle to a sports car and finally a jet to take down a secret terrorist organization in this fast-paced classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('action-fighter-usa-europe-v12', 'Master System', 'Action Fighter (USA, Europe) (v1.2)', '1986', 'Shooter', 'Sega', '1', 'Arcade', 'Transformation-based vehicular combat.', 'Infiltrate enemy bases by land and air.', 'Updated version of the vehicle transformation combat game.', 'This updated version of Action Fighter brings refined mechanics to the transforming vehicle genre. Race against time and enemies as you master land and air combat in a quest to save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-the-europe', 'Master System', 'Addams Family, The (Europe)', '1993', 'Platform', 'Arc Developments', '1', 'Cartoon', 'Side-scrolling platforming and exploration.', 'Rescue family members trapped in the mansion.', 'A spooky platformer based on the iconic movie family.', 'Join Gomez in The Addams Family as you navigate a trap-filled mansion. This SEO-optimized platformer features hidden secrets, challenging bosses, and the eerie atmosphere fans of the franchise love.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerial-assault-europe', 'Master System', 'Aerial Assault (Europe)', '1990', 'Shooter', 'Sanritsu Denki', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Destroy the enemy''s ultimate flying fortress.', 'Intense horizontal shooter with multiple power-ups.', 'Aerial Assault puts you in the cockpit of a high-tech fighter jet. Battle through five stages of intense aerial combat, upgrading your weaponry to stop a global military threat in this hidden 8-bit gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerial-assault-usa', 'Master System', 'Aerial Assault (USA)', '1990', 'Shooter', 'Sanritsu Denki', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Destroy the enemy''s ultimate flying fortress.', 'US edition of the classic horizontal shooter.', 'Experience the US version of Aerial Assault, featuring smooth side-scrolling action and challenging boss fights. Perfect for fans of 8-bit shmup history looking for precise controls and tactical upgrades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('after-burner-world', 'Master System', 'After Burner (World)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Pseudo-3D cockpit flight combat.', 'Shoot down enemy waves and reach base.', 'High-speed arcade flight combat with 360-degree rotation.', 'After Burner brings the legendary arcade experience to your home. Lock on your missiles and engage your afterburners in this fast-paced, pseudo-3D flight simulator that pushed the Master System hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-rescue-europe', 'Master System', 'Air Rescue (Europe)', '1992', 'Action', 'Sims', '1', 'Arcade', 'First-person/Side-scrolling rescue simulation.', 'Rescue hostages using a specialized helicopter.', 'Unique helicopter rescue mission with mixed perspectives.', 'Air Rescue combines a top-down perspective with side-scrolling action. Navigate dangerous territory to extract hostages, offering a unique tactical experience for Sega Master System enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-europe', 'Master System', 'Aladdin (Europe)', '1994', 'Platform', 'SIMS', '1', 'Cartoon', 'Cinematic side-scrolling platformer.', 'Rescue Princess Jasmine and defeat Jafar.', 'Stunning 8-bit platformer based on the Disney film.', 'Disney''s Aladdin on the Master System is a graphical marvel. Navigate the streets of Agrabah and the Cave of Wonders in this polished platformer that captures the magic of the animated classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aleste-japan', 'Master System', 'Aleste (Japan)', '1988', 'Shooter', 'Compile', '1', 'Anime', 'Vertical scrolling shoot ''em up.', 'Defeat the bio-mechanical entity "ALESTE".', 'Fast-paced, high-intensity vertical shooter.', 'Aleste is a Master System masterpiece known for its incredible speed and weapon variety. Defend the world against a rogue supercomputer in one of the most technically impressive shooters of the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd---high-tech-world-usa-europe', 'Master System', 'Alex Kidd - High-Tech World (USA, Europe)', '1989', 'Action', 'Sega', '1', 'Cartoon', 'Adventure and puzzle-solving.', 'Navigate a tech-filled castle to find a map.', 'A unique departure for Alex Kidd, focused on puzzles.', 'Alex Kidd: High-Tech World mixes adventure gaming with platforming elements. Solve intricate puzzles and navigate a complex castle in this localized version of the Japanese classic "Anmitsu Hime."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd---the-lost-stars-world', 'Master System', 'Alex Kidd - The Lost Stars (World)', '1986', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Collect miracle balls across different planets.', 'Arcade-style platformer featuring the Sega mascot.', 'In The Lost Stars, Alex Kidd travels through surreal dreamscapes. This port of the arcade original features vibrant colors and unique enemies, making it a standout title in the Alex Kidd franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd-bmx-trial-japan', 'Master System', 'Alex Kidd BMX Trial (Japan)', '1987', 'Sports', 'Sega', '1', 'Arcade', 'Top-down racing and navigation.', 'Reach the finish line using a BMX bike.', 'A paddle-controller compatible bike racing game.', 'Alex Kidd BMX Trial offers unique top-down racing action. Navigate obstacle courses and manage your stamina in this Japanese exclusive that showcases the versatility of the Master System library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd-in-miracle-world-usa-europe', 'Master System', 'Alex Kidd in Miracle World (USA, Europe)', '1986', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer with Janken.', 'Defeat Janken the Great and find the King.', 'The definitive Sega Master System platformer.', 'Alex Kidd in Miracle World is a foundational 8-bit classic. Featuring the iconic "Rock, Paper, Scissors" boss battles and vehicle stages, it remains a must-play title for any retro gaming fan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd-in-miracle-world-usa-europe-v11', 'Master System', 'Alex Kidd in Miracle World (USA, Europe) (v1.1)', '1986', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer with Janken.', 'Defeat Janken the Great and find the King.', 'Revised version of the legendary platformer.', 'This version 1.1 of Miracle World offers the same legendary gameplay with minor bug fixes. Experience the definitive adventure of Alex Kidd as he uses his punches and gadgets to save Radaxian.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd-in-shinobi-world-usa-europe', 'Master System', 'Alex Kidd in Shinobi World (USA, Europe)', '1987', 'Action', 'Sega', '1', 'Cartoon', 'Side-scrolling action platformer.', 'Master ninja skills to defeat the Dark Ninja.', 'A crossover between Alex Kidd and the Shinobi world.', 'Alex Kidd in Shinobi World is a brilliant parody/crossover. Combining Alex''s charm with Shinobi''s combat mechanics, it offers some of the tightest platforming controls found on the Sega Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd-no-miracle-world-japan', 'Master System', 'Alex Kidd no Miracle World (Japan)', '1986', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer with Janken.', 'Defeat Janken the Great and find the King.', 'Original Japanese version of the platforming classic.', 'Experience the Japanese roots of Sega''s first mascot. Alex Kidd no Miracle World features the original rice ball (Onigiri) power-up and the classic challenging levels that defined a generation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alf-usa', 'Master System', 'Alf (USA)', '1990', 'Platform', 'Sega', '1', 'Cartoon', 'Point-and-click adventure.', 'Complete mundane tasks and solve puzzles.', 'A rare adventure game based on the 80s TV alien.', 'Alf brings the sarcastic extraterrestrial to the Master System. Explore his neighborhood, collect items, and solve puzzles in this unique adventure title that remains a sought-after collectible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-3-europe', 'Master System', 'Alien 3 (Europe)', '1992', 'Action Probe Software', '1', 'Movie', NULL, 'Side-scrolling action platformer.', 'Rescue prisoners and destroy Xenomorph nests.', 'Dark, atmospheric action based on the sci-fi film.', 'Alien 3 offers a tense, race-against-the-clock experience. As Ellen Ripley, use a variety of weapons to save prisoners from the alien threat in this technically impressive 8-bit cinematic adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-storm-europe', 'Master System', 'Alien Storm (Europe)', '1991', 'Action', 'Sega', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Defeat the alien invaders and rescue humans.', 'Tactical combat with diverse character classes.', 'Alien Storm is a fantastic port of the arcade hit. Choose your hero and battle shape-shifting aliens across city streets in this action-packed blend of beat ''em up and shooting gallery stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-syndrome-japan', 'Master System', 'Alien Syndrome (Japan)', '1988', 'Action', 'Sega', '2', 'Arcade', 'Top-down run and gun shooter.', 'Rescue hostages and escape before the bomb explodes.', 'Fast-paced sci-fi horror action for two players.', 'Alien Syndrome delivers intense top-down shooting. Navigate labyrinthine space stations, rescue your crew, and face off against massive, grotesque bosses in this faithful Japanese arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-syndrome-usa-europe', 'Master System', 'Alien Syndrome (USA, Europe)', '1988', 'Action', 'Sega', '2', 'Arcade', 'Top-down run and gun shooter.', 'Rescue hostages and escape before the bomb explodes.', 'The international version of the sci-fi horror shooter.', 'Brave the horrors of space in Alien Syndrome. This version brings the iconic rescue-and-escape gameplay to western audiences, featuring tight controls and a memorable co-op experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('altered-beast-usa-europe', 'Master System', 'Altered Beast (USA, Europe)', '1988', 'Beat ''em up', 'Sega', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Fight through hordes of monsters to save Athena.', 'Classic arcade port featuring beast transformations.', '"Rise from your grave!" Altered Beast on the Master System lets you transform into powerful creatures to battle the underworld. A faithful recreation of the arcade''s atmosphere and power-up system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-baseball-europe', 'Master System', 'American Baseball (Europe)', '1989', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation.', 'Win the baseball league championship.', 'Realistic baseball sim with multiple teams.', 'American Baseball offers a comprehensive diamond experience. With strategic pitching and batting mechanics, it provides a solid sports simulation for fans looking for a competitive 8-bit challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-pro-football-europe', 'Master System', 'American Pro Football (Europe)', '1989', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation.', 'Score touchdowns and win the championship.', 'American football simulation with tactical plays.', 'American Pro Football brings the gridiron to the Master System. Choose your plays and execute passes or runs in this sports title designed for fans of strategy and fast-paced athletic action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('amy-in-sonic-the-hedgehog', 'Master System', 'Amy in Sonic The Hedgehog', '1996', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Finish levels as fast as possible.', 'A fan-favorite hack featuring Amy Rose in Sonic 1.', 'Amy in Sonic the Hedgehog is a unique modification that lets you play the 8-bit Sonic classic as Amy Rose. Experience familiar levels with a fresh perspective and character sprite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ancient-ys-vanished-omen-japan', 'Master System', 'Ancient Ys Vanished Omen (Japan)', '1987', 'RPG', 'Nihon Falcom', '1', 'Anime', 'Action RPG.', 'Explore the land of Esteria and find the 6 books.', 'The legendary first entry in the Ys series.', 'Ancient Ys Vanished Omen is a pioneer of the Action RPG genre. Featuring the unique "bump" combat system and an incredible soundtrack, this Japanese version is a piece of gaming history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ancient-ys-vanished-omen-usa-europe', 'Master System', 'Ancient Ys Vanished Omen (USA, Europe)', '1987', 'RPG', 'Nihon Falcom', '1', 'Anime', 'Action RPG.', 'Explore the land of Esteria and find the 6 books.', 'The localized version of the classic Ys RPG.', 'Ys: The Vanished Omens (USA/Europe) brings Adol Christin''s first adventure to the West. Explore deep dungeons and engage in fast-paced combat in one of the most influential RPGs on the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('andre-agassi-tennis-europe', 'Master System', 'Andre Agassi Tennis (Europe)', '1993', 'Sports', 'Sims', '2', 'Realistic', 'Sports simulation.', 'Win the tennis tournament against top pros.', 'Professional tennis simulation endorsed by Agassi.', 'Andre Agassi Tennis offers precise controls and multiple surface types. Master your serve and volley in this sports title that captures the intensity of professional tennis on an 8-bit scale.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anmitsu-hime-japan', 'Master System', 'Anmitsu Hime (Japan)', '1986', 'Platform', 'Sega', '1', 'Cartoon', 'Point-and-click adventure.', 'Navigate the castle and solve puzzles to escape.', 'A charming Japanese adventure game based on the manga.', 'Anmitsu Hime is the original Japanese version of what became Alex Kidd: High-Tech World. Experience the authentic story of the titular princess in this detailed 8-bit adventure filled with humor and cultural references.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcade-smash-hits-europe', 'Master System', 'Arcade Smash Hits (Europe)', '1990', 'Compilation', 'Sega', '1', 'Various', 'Compilation of arcade classics.', 'Achieve high scores in Centipede, Missile Command, and Breakout.', 'A three-in-one collection of legendary Atari arcade hits.', 'Arcade Smash Hits brings the golden age of gaming to your Master System. Enjoy faithful ports of Centipede, Missile Command, and Breakout, offering addictive retro gameplay and high-score chasing in one package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('argos-no-juujiken-japan', 'Master System', 'Argos no Juujiken (Japan)', '1987', 'Action', 'Sega', '1', 'Arcade', 'Side-scrolling action platformer.', 'Defeat the Ligar beast and rescue the world.', 'The Japanese version of the legendary Rygar.', 'Argos no Juujiken is a fast-paced action game featuring a unique "Diskarmor" weapon. Battle through mythological landscapes and defeat massive bosses in this challenging 8-bit port of the arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ariel---the-little-mermaid-brazil', 'Master System', 'Ariel - The Little Mermaid (Brazil)', '1994', 'Platform', 'Simms', '1', 'Cartoon', 'Underwater side-scrolling action.', 'Rescue sea creatures and defeat Ursula.', 'A Brazil-exclusive adaptation of Disney''s Mermaid.', 'Ariel - The Little Mermaid takes you under the sea for a unique adventure. Exclusive to the Brazilian market, this title features vibrant colors and accessible gameplay perfect for fans of the Disney Princess franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ashura-japan', 'Master System', 'Ashura (Japan)', '1987', 'Action', 'Sega', '1', 'Arcade', 'Top-down run and gun shooter.', 'Infiltrate enemy territory and rescue captives.', 'The original Japanese release of the classic Rambo game.', 'Ashura offers intense overhead shooting action. Navigate through jungles and military bases, using your machine gun and limited grenades to take down an army in this high-octane Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('assault-city-europe', 'Master System', 'Assault City (Europe)', '1990', 'Action', 'Sega', '2', 'Arcade', 'Light phaser shooting gallery.', 'Destroy the robotic uprising in a futuristic city.', 'A sci-fi light gun shooter with intense action.', 'Assault City puts your reflexes to the test. Compatible with the Light Phaser, this game tasks you with stopping a rogue AI by blasting through waves of hostile robots in a cyberpunk urban setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-europe-enfr', 'Master System', 'Asterix (Europe) (En,Fr)', '1991', 'Platform', 'Infogrames', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Obelix from the clutches of the Romans.', 'A polished platformer starring the famous Gaul.', 'Asterix is a masterpiece of 8-bit level design. Play as Asterix as you travel across Europe to save your best friend, featuring incredible graphics and secret-filled stages that push the hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-europe-enfr-v11', 'Master System', 'Asterix (Europe) (En,Fr) (v1.1)', '1991', 'Platform', 'Infogrames', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Obelix from the clutches of the Romans.', 'Updated version of the classic Gaulish adventure.', 'This v1.1 release of Asterix provides the same high-quality platforming with minor technical refinements. Explore varied levels from the forest to Rome in one of the most beloved licensed games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-and-the-great-rescue-europe-enfrdeesit', 'Master System', 'Asterix and the Great Rescue (Europe) (En,Fr,De,Es,It)', '1993', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling action platformer.', 'Save Getafix and Dogmatix from the Romans.', 'A challenging multi-language platformer adventure.', 'Asterix and the Great Rescue features large, detailed sprites and a high difficulty level. Navigate treacherous traps and Roman legions in this visually stunning late-era Master System release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-and-the-secret-mission-europe-enfrde', 'Master System', 'Asterix and the Secret Mission (Europe) (En,Fr,De)', '1993', 'Platform', 'Core Design', '1', 'Cartoon', 'Multi-path side-scrolling platformer.', 'Find the secret potion ingredients to save the village.', 'A non-linear platformer featuring Asterix and Obelix.', 'Asterix and the Secret Mission allows you to choose between Asterix or Obelix for different gameplay styles. Explore branching paths and beautiful environments in this quest to restore the Gauls'' strength.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astro-flash-japan', 'Master System', 'Astro Flash (Japan)', '1986', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Navigate a space station and destroy the core.', 'The Japanese version of the sci-fi shooter TransBot.', 'Astro Flash is a fast-paced "shmup" where your ship can transform. Battle through mechanical corridors and upgrade your weapons to survive the onslaught in this early Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astro-warrior-japan-usa', 'Master System', 'Astro Warrior (Japan, USA)', '1986', 'Shooter', 'Sega', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Destroy the supercomputer controlling the galaxy.', 'A pure, high-speed vertical space shooter.', 'Astro Warrior is a masterclass in 8-bit shooter simplicity. Collect power-ups to increase your fire spread and speed as you tackle three massive levels filled with challenging enemy formations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astro-warrior-&-pit-pot-europe', 'Master System', 'Astro Warrior & Pit Pot (Europe)', '1986', 'Shooter', 'Sega', '1', 'Arcade', 'Compilation of shooter and puzzle.', 'Master space combat and solve block-pushing puzzles.', 'A diverse two-game pack for the Master System.', 'This European duo offers the space combat of Astro Warrior alongside the strategic, top-down puzzle-solving of Pit Pot. A perfect mix of high-speed action and brain-teasing navigation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ayrton-sennas-super-monaco-gp-ii-europe', 'Master System', 'Ayrton Senna''s Super Monaco GP II (Europe)', '1992', 'Racing', 'Sega', '1', 'Simulation', 'Formula One racing simulation.', 'Win the F1 World Championship with Senna''s guidance.', 'The definitive 8-bit Formula One racing game.', 'Super Monaco GP II features the expertise of Ayrton Senna. With improved handling and a deep career mode, it stands as the premier racing experience for the Master System, complete with real-world tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aztec-adventure---the-golden-road-to-paradise-world', 'Master System', 'Aztec Adventure - The Golden Road to Paradise (World)', '1987', 'Action', 'Sega', '1', 'Arcade', 'Isometric action adventure.', 'Reach the Golden Temple by bribing or fighting.', 'A unique Aztec-themed adventure with AI companions.', 'Aztec Adventure challenges you to navigate a dangerous "Golden Road." Use money to recruit enemies to fight alongside you in this colorful and strategically deep isometric quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('back-to-the-future-part-ii-europe', 'Master System', 'Back to the Future Part II (Europe)', '1990', 'Action', 'Image Works', '1', 'Movie', 'Side-scrolling action platformer.', 'Travel through time to fix the future.', 'A movie-based platformer with varied gadget use.', 'Back to the Future Part II tasks Marty McFly with navigating 2015. Use the hoverboard and avoid Biff''s gang in this challenging adaptation that captures the frantic energy of the sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('back-to-the-future-part-iii-europe', 'Master System', 'Back to the Future Part III (Europe)', '1991', 'Action', 'Image Works', '1', 'Movie', 'Side-scrolling action and shooting.', 'Defeat Buford Tannen and return to 1885.', 'A multi-genre adventure based on the Western finale.', 'Back to the Future Part III features distinct levels ranging from horse-riding chases to shooting galleries. Follow the plot of the third film as you help Doc and Marty fix the timeline one last time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baku-baku-animal-brazil', 'Master System', 'Baku Baku Animal (Brazil)', '1996', 'Puzzle', 'Sega', '2', 'Cute', 'Puzzle-solving tile matcher.', 'Match animal tiles with their favorite foods.', 'A fast-paced arcade puzzle game with animals.', 'Baku Baku Animal is a cult classic puzzle game. With its unique "predator and prey" matching mechanic, it offers a frantic and colorful competitive experience that is both easy to learn and hard to master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bank-panic-europe', 'Master System', 'Bank Panic (Europe)', '1987', 'Action', 'Sega', '1', 'Arcade', 'First-person reaction shooter.', 'Shoot the outlaws while sparing the civilians.', 'A Wild West arcade port with timing-based combat.', 'Bank Panic is all about speed and precision. Guard the bank doors, react to the bandits, and collect bags of gold in this high-tension arcade conversion that rewards perfect timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('basket-ball-nightmare-europe', 'Master System', 'Basket Ball Nightmare (Europe)', '1992', 'Sports', 'Sega', '1', 'Arcade', 'Sports simulation with horror theme.', 'Win the basketball tournament against monsters.', 'A spooky twist on traditional basketball gameplay.', 'Basketball Nightmare takes the sport to a haunted realm. Face off against vampires, ghosts, and werewolves in this creative sports title that features unique court visuals and solid mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-returns-europe', 'Master System', 'Batman Returns (Europe)', '1992', 'Action', 'Sega', '1', 'Movie', 'Side-scrolling beat ''em up.', 'Stop the Penguin and Catwoman in Gotham City.', 'A dark, atmospheric action game based on the movie.', 'Batman Returns is one of the best-looking games on the system. Choose between high and low routes through Gotham, using your batarangs and grappling hook to defeat the Red Triangle Circus Gang.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-out-run-europe', 'Master System', 'Battle Out Run (Europe)', '1989', 'Racing', 'Sega', '1', 'Arcade', 'Combat-based racing.', 'Race across the US while taking down rival cars.', 'A unique blend of Out Run and vehicular combat.', 'Battle Out Run adds a tactical twist to the racing franchise. Upgrade your car''s engine, tires, and chassis to better ram enemies off the road while chasing a high-speed criminal across the country.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battlemaniacs-brazil', 'Master System', 'Battlemaniacs (Brazil)', '1991', 'Action', 'Sims', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Defeat the Dark Queen and save your friends.', 'A high-difficulty, intense action brawler.', 'Battlemaniacs brings the world of Battletoads to the Master System. Known for its punishing difficulty and varied levels—including the infamous speed bike stages—it is a true test for any retro gamer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('black-belt-usa-europe', 'Master System', 'Black Belt (USA, Europe)', '1986', 'Action', 'Sega', '1', 'Martial Arts', 'Side-scrolling martial arts combat.', 'Defeat the seven martial arts masters.', 'A high-energy fighting game based on Hokuto no Ken.', 'Black Belt is the Western localization of Fist of the North Star. Battle through waves of minions before engaging in cinematic, one-on-one boss fights that defined the 8-bit brawler genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blade-eagle-world', 'Master System', 'Blade Eagle (World)', '1988', 'Shooter', 'Sega', '1', 'Arcade', '3D vertical scrolling shooter.', 'Destroy the alien fortress in the third dimension.', 'A unique 3D shooter designed for Sega''s 3D Glasses.', 'Blade Eagle (3D) offers a sense of depth rare for the era. Fly your jet through multiple layers of enemy fire, utilizing the Master System''s 3D capabilities for a truly immersive retro experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomber-raid-world', 'Master System', 'Bomber Raid (World)', '1988', 'Shooter', 'Sega', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Destroy the enemy''s secret weapon and base.', 'A classic military-themed vertical shooter.', 'Bomber Raid is a polished "shmup" where you pilot a powerful bomber. Collect "P" icons to boost your firepower and deploy devastating cluster bombs to clear the screen of enemy aircraft and ships.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonanza-bros-europe', 'Master System', 'Bonanza Bros. (Europe)', '1991', 'Action', 'Sega', '2', 'Cartoon', 'Side-scrolling action platformer.', 'Infiltrate buildings and recover target items.', 'A stealth-lite arcade port with 2-player co-op.', 'Bonanza Bros. features a unique "paper-thin" art style. Play as Mobo and Robo as you sneak past guards, use traps, and execute the perfect heist in this charming and stylish Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonkers-wax-up!-brazil', 'Master System', 'Bonkers Wax Up! (Brazil)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save the cartoon world by cleaning up messes.', 'A late-era Disney platformer with vibrant graphics.', 'Bonkers Wax Up! is a Brazil-exclusive title featuring the energetic bobcat. Navigate through wacky environments and use Bonkers'' agility to defeat villains in this polished and rare 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bram-stokers-dracula-europe', 'Master System', 'Bram Stoker''s Dracula (Europe)', '1993', 'Action', 'Psygnosis', '1', 'Horror', 'Side-scrolling action.', 'Hunt down Dracula across different time periods.', 'A dark action game based on the 1992 film.', 'Bram Stoker''s Dracula offers a gloomy atmosphere and challenging combat. Navigate through forests and castles, using multiple weapons to fight off the undead in this cinematic 8-bit horror adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble-europe', 'Master System', 'Bubble Bobble (Europe)', '1988', 'Platform', 'Toei Animation', '2', 'Cute', 'Fixed-screen platformer.', 'Trap enemies in bubbles and pop them for points.', 'A legendary arcade port with 100 levels.', 'Bubble Bobble is a perfect conversion for the Master System. Play as Bub or Bob in a quest through 100 monster-filled stages, collecting fruit and power-ups in one of the most addictive games ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buggy-run-europe', 'Master System', 'Buggy Run (Europe)', '1987', 'Racing', 'Sega', '1', 'Arcade', 'Top-down vehicular combat racing.', 'Win races and upgrade your buggy with weapons.', 'A frantic combat racer with a shop system.', 'Buggy Run delivers high-octane overhead racing. Compete in diverse environments, use earned prize money to customize your vehicle, and outmaneuver rivals in this late-gen Master System gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('california-games-usa-europe', 'Master System', 'California Games (USA, Europe)', '1987', 'Sports', 'Epyx', '4', 'Arcade', 'Multi-event sports simulation.', 'Achieve the highest score in extreme sports.', 'A classic collection of California-style sports.', 'California Games is the ultimate retro sports anthology. Master the half-pipe, footbag, surfing, skating, and more to become the champion of the Golden State in this iconic 8-bit port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('california-games-ii-brazil-korea', 'Master System', 'California Games II (Brazil, Korea)', '1989', 'Sports', 'Epyx', '4', 'Arcade', 'Multi-event sports simulation.', 'Compete in hang gliding, jet skiing, and more.', 'The Brazilian sequel to the extreme sports hit.', 'California Games II introduces brand new events like snowboarding and bodyboarding. This version brings enhanced variety and challenging mechanics to fans of the classic sports franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('california-games-ii-europe', 'Master System', 'California Games II (Europe)', '1989', 'Sports', 'Epyx', '4', 'Arcade', 'Multi-event sports simulation.', 'Compete in hang gliding, jet skiing, and more.', 'The European release of the extreme sports sequel.', 'Experience the thrill of new extreme sports in California Games II. This European edition features improved physics and diverse events that push your skills across land, sea, and air.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-silver-japan-europe', 'Master System', 'Captain Silver (Japan, Europe)', '1988', 'Action', 'Sega', '1', 'Arcade', 'Side-scrolling hack and slash.', 'Defeat ghost pirates to find Captain Silver''s treasure.', 'A swashbuckling adventure with a magic sword.', 'Captain Silver (EU/JP) is a full-length pirate adventure. Battle through ports and haunted ships to claim legendary loot in this action-packed side-scroller featuring challenging boss encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-silver-usa', 'Master System', 'Captain Silver (USA)', '1988', 'Action', 'Sega', '1', 'Arcade', 'Side-scrolling hack and slash.', 'Defeat ghost pirates to find Captain Silver''s treasure.', 'A condensed version of the pirate action game.', 'This US version of Captain Silver offers a streamlined experience of the arcade original. Fast-paced swordplay and maritime myths make it a unique addition to the Master System action library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('casino-games-usa-europe', 'Master System', 'Casino Games (USA, Europe)', '1989', 'Card', 'Sega', '2', 'Board', 'Gambling and card game simulation.', 'Win big in Poker, Blackjack, and Baccarat.', 'A comprehensive virtual casino experience.', 'Casino Games brings the Las Vegas strip to your living room. Test your luck and strategy in multiple gambling classics, including slot machines and pinball, to build your virtual fortune.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castelo-ra-tim-bum-brazil', 'Master System', 'Castelo Ra-Tim-Bum (Brazil)', '1994', 'Educational', 'Tectoy', '1', 'Cartoon', 'Side-scrolling adventure platformer.', 'Explore the castle to find items and solve mysteries.', 'A Brazilian exclusive based on the popular TV show.', 'Castelo Rá-Tim-Bum is a rare treasure for collectors. Based on the Brazilian cult hit show, play as Nino and navigate the magical castle in this charming and colorful platforming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castle-of-illusion-starring-mickey-mouse-europe', 'Master System', 'Castle of Illusion Starring Mickey Mouse (Europe)', '1990', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Collect seven gems to rescue Minnie from Mizrabel.', 'A masterpiece of 8-bit Disney platforming.', 'Castle of Illusion Starring Mickey Mouse is widely considered one of the best games on the system. Featuring tight controls and incredible visuals, Mickey must brave enchanted worlds to save Minnie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castle-of-illusion-starring-mickey-mouse-usa', 'Master System', 'Castle of Illusion Starring Mickey Mouse (USA)', '1990', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Collect seven gems to rescue Minnie from Mizrabel.', 'The North American release of Mickey''s classic quest.', 'Relive the magic of Disney''s finest 8-bit hour. Navigate the Library and the Toy Factory in this perfectly paced platformer that remains a gold standard for the Sega Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('champions-of-europe-europe', 'Master System', 'Champions of Europe (Europe)', '1992', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation.', 'Win the European football championship.', 'An officially licensed soccer game for Euro ''92.', 'Champions of Europe offers fast-paced football action. Lead your favorite national team to glory through the tournament brackets in this competitive and responsive sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('championship-hockey-europe', 'Master System', 'Championship Hockey (Europe)', '1991', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation.', 'Outscore the opponent in professional hockey.', 'A fluid and fast-paced ice hockey simulator.', 'Championship Hockey brings the intensity of the rink to the Master System. With smooth skating mechanics and tactical gameplay, it''s a must-play for fans of 8-bit winter sports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chapolim-x-dracula---um-duelo-assustador-brazil', 'Master System', 'Chapolim x Dracula - Um Duelo Assustador (Brazil)', '1993', 'Platform', 'Tectoy', '1', 'Cartoon', 'Side-scrolling action platformer.', 'Defeat Dracula and his monsters.', 'A Brazilian re-skin of Ghost House featuring Chapolim.', 'Chapolim x Dracula is a unique cultural crossover. Play as the iconic comedy hero "El Chapulín Colorado" as he explores a haunted mansion in this modified version of the Sega classic Ghost House.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cheese-cat-astrophe-starring-speedy-gonzales-europe-enfrdees', 'Master System', 'Cheese Cat-astrophe Starring Speedy Gonzales (Europe) (En,Fr,De,Es)', '1995', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue your friends from the villainous cats.', 'A vibrant platformer featuring the fastest mouse.', 'Cheese Cat-astrophe stars Speedy Gonzales in a visually stunning adventure. Use your speed and reflexes to outsmart enemies in this late-release title known for its high-quality animation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choplifter-japan-proto', 'Master System', 'Choplifter (Japan) (Proto)', '1985', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling rescue simulation.', 'Fly a helicopter to rescue POWs behind enemy lines.', 'Prototype version of the legendary rescue game.', 'This prototype of Choplifter offers a look into the development of a classic. Navigate dangerous airspace and land carefully to save hostages in this foundational Sega action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choplifter-usa-europe', 'Master System', 'Choplifter (USA, Europe)', '1985', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling rescue simulation.', 'Fly a helicopter to rescue POWs behind enemy lines.', 'The definitive 8-bit port of the arcade hit.', 'Choplifter is a Master System essential. Balance combat and precision flying as you extract prisoners from enemy territory, avoiding tanks and fighter jets in this high-stakes mission.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chouon-senshi-borgman-japan', 'Master System', 'Chouon Senshi Borgman (Japan)', '1988', 'Action', 'Sega', '1', 'Anime', 'Side-scrolling action shooter.', 'Defeat the cyborg invasion and save the city.', 'The Japanese version of the Borgman action game.', 'Chouon Senshi Borgman is a sci-fi brawler/shooter based on the anime. Use powerful armor and weapons to clear stages and defeat massive bosses in this high-tech 8-bit struggle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-europe', 'Master System', 'Chuck Rock (Europe)', '1991', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue your girlfriend from a rival caveman.', 'A humorous prehistoric action-adventure.', 'Chuck Rock brings belly-smashing action to the Stone Age. Use your environment and your iconic "belly butt" to defeat dinosaurs and navigate creative levels in this charismatic platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-ii---son-of-chuck-brazil', 'Master System', 'Chuck Rock II - Son of Chuck (Brazil)', '1993', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Chuck Rock as his club-wielding son.', 'Brazilian release of the prehistoric sequel.', 'Chuck Rock II: Son of Chuck features more refined gameplay and adorable visuals. Play as Junior and use your rattle-club to bash enemies and rescue your father in this polished sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-ii---son-of-chuck-europe', 'Master System', 'Chuck Rock II - Son of Chuck (Europe)', '1993', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Chuck Rock as his club-wielding son.', 'The European edition of the caveman sequel.', 'Junior takes center stage in Chuck Rock II. This European version showcases impressive 8-bit graphics and more complex level design, making it a standout late-era platformer for the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('circuit-the-japan', 'Master System', 'Circuit, The (Japan)', '1986', 'Puzzle', 'Sega', '1', 'Abstract', 'Top-down racing simulation.', 'Win the Formula One World Championship.', 'A technical F1 racer with car customization.', 'The Circuit (known as World Grand Prix in some regions) focuses on precision and speed. Tune your car and master every turn to climb the rankings in this challenging 8-bit racing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cloud-master-usa-europe', 'Master System', 'Cloud Master (USA, Europe)', '1989', 'Shooter', 'Sims', '1', 'Arcade', 'Horizontal scrolling shoot ''em up.', 'Fly on a cloud and defeat mythological bosses.', 'A whimsical and challenging "cute ''em up."', 'Cloud Master (Chuka Taisen) takes you on a journey through ancient China. Ride your cloud, upgrade your magic shots, and face off against bizarre deities in this colorful arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('color-&-switch-test-unknown-v13', 'Master System', 'Color & Switch Test (Unknown) (v1.3)', '1990', 'Test', 'Sega', '1', 'Utility', 'Hardware diagnostic tool.', 'Test the console''s color palette and switches.', 'A technical utility for testing system hardware.', 'The Color & Switch Test is an interesting piece of Sega history. Used primarily by technicians, it allows for the calibration of colors and the testing of input responsiveness on the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-usa-europe', 'Master System', 'Columns (USA, Europe)', '1990', 'Puzzle', 'Sega', '2', 'Abstract', 'Falling block puzzle.', 'Match three or more jewels of the same color.', 'The definitive 8-bit jewel matching puzzle.', 'Columns is Sega''s elegant answer to the puzzle genre. Featuring an addictive "match-three" mechanic and a relaxing soundtrack, it remains one of the most played titles on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('comical-machine-gun-joe-japan', 'Master System', 'Comical Machine Gun Joe (Japan)', '1986', 'Action', 'Sega', '1', 'Cartoon', 'Top-down run and gun shooter.', 'Defeat outlaws in a wacky Western setting.', 'A quirky and fast-paced cowboy shooter.', 'Comical Machine Gun Joe features high-speed action and a unique art style. Maneuver through waves of bandits in this Japanese exclusive that offers a lighthearted take on the shooter genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cool-spot-europe', 'Master System', 'Cool Spot (Europe)', '1993', 'Platform', 'Virgin Interactive', '1', 'Cartoon', 'Side-scrolling platformer.', 'Collect spots and rescue your friends.', 'A stylish platformer based on the 7-Up mascot.', 'Cool Spot is a masterclass in 8-bit animation and music. Navigate beaches and toy rooms with the coolest mascot of the 90s in this challenging and visually impressive adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmic-spacehead-europe-enfrdees', 'Master System', 'Cosmic Spacehead (Europe) (En,Fr,De,Es)', '1992', 'Adventure', 'Codemasters', '1', 'Cartoon', 'Multi-genre adventure.', 'Find the three missing pieces of your spaceship.', 'A unique mix of platforming and point-and-click.', 'Cosmic Spacehead takes you on a quirky intergalactic quest. Solve puzzles and complete action stages to help Cosmic return home in this vibrant and highly creative title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cream-in-sonic-the-hedgehog', 'Master System', 'Cream in Sonic The Hedgehog', '1996', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Finish levels as fast as possible.', 'A fan-made hack featuring Cream the Rabbit.', 'Cream in Sonic the Hedgehog allows you to play the original 8-bit Sonic adventure with a custom Cream the Rabbit sprite. A fun, modern twist on a classic Sega Master System title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-shinobi-the-europe', 'Master System', 'Cyber Shinobi, The (Europe)', '1990', 'Action', 'Sega', '1', 'Ninja', 'Side-scrolling beat ''em up.', 'Stop the cyber-terrorist group and their leader.', 'A futuristic ninja action game.', 'The Cyber Shinobi is a unique entry in the Shinobi series. Battle through industrial settings with your sword and specialized power-ups to stop a nuclear threat in this 8-bit actioner.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyborg-hunter-usa-europe', 'Master System', 'Cyborg Hunter (USA, Europe)', '1988', 'Action', 'Sega', '1', 'Sci-Fi', 'Side-scrolling action adventure.', 'Explore the labyrinthine base to defeat the master.', 'A Metroid-style exploration game with upgrades.', 'Cyborg Hunter tasks you with infiltrating a massive enemy complex. Find new equipment to unlock new areas in this deep and atmospheric sci-fi adventure that rewards thorough exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daffy-duck-in-hollywood-europe-enfrdeesit', 'Master System', 'Daffy Duck in Hollywood (Europe) (En,Fr,De,Es,It)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Recover Yosemite Sam''s stolen movie awards.', 'A vibrant Looney Tunes adventure in Hollywood.', 'Daffy Duck in Hollywood features the iconic duck in a quest through movie sets. With diverse power-ups and hidden areas, this late-release title showcases the Master System''s ability to handle high-quality cartoon graphics and smooth animation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dallyeora-pigu-wang-korea-unl', 'Master System', 'Dallyeora Pigu-Wang (Korea) (Unl)', '1994', 'Platform', 'Unlicensed', '1', 'Cartoon', 'Sports simulation (Dodgeball).', 'Outplay and eliminate the opposing team.', 'A Korean exclusive dodgeball game based on anime.', 'Dallyeora Pigu-Wang brings the intensity of "Dodge Danpei" to the Master System. This rare Korean title features fast-paced arcade sports action, special power-shots, and competitive team-based gameplay for retro enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('danan---the-jungle-fighter-europe', 'Master System', 'Danan - The Jungle Fighter (Europe)', '1990', 'Action', 'U.S. Gold', '1', 'Arcade', 'Side-scrolling action RPG.', 'Rescue your friend and find the sacred jewels.', 'A jungle-themed action adventure with RPG elements.', 'Danan: The Jungle Fighter blends fast-paced combat with exploration. Level up your hero and summon animal companions to assist you in this deep, atmospheric title that stands out as one of the system''s best action-adventures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dead-angle-usa-europe', 'Master System', 'Dead Angle (USA, Europe)', '1988', 'Shooter', 'Sega', '1', 'Arcade', 'First-person shooting gallery.', 'Rescue your kidnapped girlfriend from the mob.', 'A cinematic mobster-themed target shooter.', 'Dead Angle puts you in the middle of a 1930s gang war. Use your crosshair to clear the screen of hitmen in this unique shooter that features a "silhouetted" protagonist mechanic and intense boss encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deep-duck-trouble-starring-donald-duck-europe', 'Master System', 'Deep Duck Trouble Starring Donald Duck (Europe)', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Reverse a curse placed on Uncle Scrooge.', 'A visually stunning Disney platformer starring Donald.', 'Deep Duck Trouble features incredible 8-bit graphics. Help Donald Duck navigate dangerous islands and underwater caves using his signature "butt-bounce" to solve puzzles and defeat bosses in this polished Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-speedtrap-starring-road-runner-and-wile-e-coyote-europe-enfrdeesit', 'Master System', 'Desert Speedtrap Starring Road Runner and Wile E. Coyote (Europe) (En,Fr,De,Es,It)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Outrun Wile E. Coyote and reach the finish.', 'A high-speed chase through the desert.', 'Desert Speedtrap captures the classic Looney Tunes rivalry. Use Road Runner''s incredible speed to navigate treacherous platforms while avoiding the elaborate traps of Wile E. Coyote in this challenging and colorful title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-strike-europe-enfrdees', 'Master System', 'Desert Strike (Europe) (En,Fr,De,Es)', '1992', 'Action', 'Electronic Arts', '1', 'Military', 'Isometric vehicular combat.', 'Complete tactical missions using an Apache helicopter.', 'A strategic 8-bit port of the famous strike series.', 'Desert Strike brings the hit PC and 16-bit series to the Master System. Manage your fuel and ammunition while completing rescue missions and destroying enemy installations in this complex isometric shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dick-tracy-usa-europe', 'Master System', 'Dick Tracy (USA, Europe)', '1990', 'Action', 'Titus Interactive', '1', 'Movie', 'Side-scrolling action platformer.', 'Clean up the city streets and defeat Big Boy.', 'A stylized action game based on the 1990 film.', 'Dick Tracy features a mix of platforming and shooting gallery segments. Use your tommy gun to take down famous mobsters in this atmospheric adaptation that captures the comic book aesthetic of the movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dinobasher-starring-bignose-the-caveman-europe-proto', 'Master System', 'Dinobasher Starring Bignose the Caveman (Europe) (Proto)', '1990', 'Platform', 'Codemasters', '1', 'Cartoon', 'Side-scrolling platformer.', 'Hunt for food and survive prehistoric hazards.', 'An unreleased prehistoric platformer starring Big Nose.', 'Dinobasher is a rare look at an unreleased Master System gem. Play as the club-wielding Big Nose in this colorful and fast-paced adventure through dangerous lands filled with dinosaurs and primitive traps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dinosaur-dooley-the-korea-unl', 'Master System', 'Dinosaur Dooley, The (Korea) (Unl)', '1995', 'Platform', 'Unlicensed', '1', 'Cartoon', 'Side-scrolling platformer.', 'Navigate levels and reach the goal as Dooley.', 'A rare Korean platformer based on the popular cartoon.', 'The Dinosaur Dooley (Dooly) is a charming unlicensed title from Korea. Featuring bright colors and classic platforming mechanics, it follows the adventures of the famous little dinosaur and his eclectic group of friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doki-doki-penguin-land---uchuu-daibouken-japan', 'Master System', 'Doki Doki Penguin Land - Uchuu Daibouken (Japan)', '1987', 'Puzzle', 'Sega', '2', 'Cute', 'Physics-based puzzle platformer.', 'Guide an egg to the bottom of each level.', 'A strategic puzzle game featuring a space penguin.', 'Doki Doki Penguin Land is a cult classic. Use gravity and precise digging to guide your egg safely through complex stages, avoiding enemies and traps in one of the most clever puzzle games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-world', 'Master System', 'Double Dragon (World)', '1988', 'Beat ''em up', 'Technos Japan', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Rescue Marian from the Black Warriors gang.', 'The legendary 8-bit port of the arcade brawler.', 'Double Dragon on the Master System is renowned for its depth, featuring more items and moves than other 8-bit versions. Battle through the city and the woods to save your girlfriend in this quintessential brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-hawk-europe', 'Master System', 'Double Hawk (Europe)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Third-person light gun shooter.', 'Defeat the terrorist group and stop their leader.', 'A high-octane 2-player light gun experience.', 'Double Hawk is a rare Light Phaser title that supports two players simultaneously. Blast your way through enemy-filled screens in this arcade-style shooter that features some of the best gunplay on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-hawk-europe-beta', 'Master System', 'Double Hawk (Europe) (Beta)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Third-person light gun shooter.', 'Defeat the terrorist group and stop their leader.', 'Beta version of the dual-player light gun shooter.', 'This beta version of Double Hawk offers a glimpse into the game''s development. Experience the same intense light gun action with slight variations in mechanics and enemy placement compared to the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-target---cynthia-no-nemuri-japan', 'Master System', 'Double Target - Cynthia no Nemuri (Japan)', '1988', 'Action', 'Sega', '1', 'Anime', 'Top-down run and gun shooter.', 'Rescue the sleeping princess Cynthia.', 'A sci-fi shooter featuring a female protagonist.', 'Double Target (Quartet) is a fast-paced overhead shooter. Fight your way through mechanical corridors, collect power-ups, and defeat massive bosses in this colorful and challenging Japanese arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-robotniks-mean-bean-machine-europe', 'Master System', 'Dr. Robotnik''s Mean Bean Machine (Europe)', '1993', 'Puzzle', 'Sega', '2', 'Cute', 'Falling block puzzle.', 'Group colored beans to clear them from the board.', 'A Sonic-themed reskin of Puyo Puyo.', 'Dr. Robotnik''s Mean Bean Machine is a competitive puzzle masterpiece. Match four beans of the same color to send "garbage" to your opponent''s screen in this highly addictive and strategic 8-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon---the-bruce-lee-story-europe', 'Master System', 'Dragon - The Bruce Lee Story (Europe)', '1993', 'Action', 'Virgin Interactive', '1', 'Movie', 'One-on-one fighting game.', 'Master the art of Jeet Kune Do.', 'A cinematic fighter based on the Bruce Lee biopic.', 'Dragon: The Bruce Lee Story features fluid animation and challenging combat. Battle through different eras of Bruce Lee''s life, mastering his legendary techniques in this late-era Master System fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-crystal-europe', 'Master System', 'Dragon Crystal (Europe)', '1990', 'RPG', 'Sega', '1', 'Fantasy', 'Isometric roguelike RPG.', 'Traverse 30 levels of the dungeon to find the orb.', 'A challenging and colorful 8-bit dungeon crawler.', 'Dragon Crystal is a deep, turn-based RPG. With randomly generated levels and a wide array of weapons and armor, no two adventures are ever the same in this portable-to-home console masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-duke-europe', 'Master System', 'Dynamite Duke (Europe)', '1989', 'Action', 'Sega', '2', 'Arcade', 'Third-person rail shooter.', 'Infiltrate the enemy base and stop the mad scientist.', 'A fast-paced shooter with a "brawl" mechanic.', 'Dynamite Duke combines rail shooting with close-quarters combat. Use your cybernetic arm to blast and punch through enemy waves in this intense arcade port that features high-speed action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-dux-europe', 'Master System', 'Dynamite Dux (Europe)', '1988', 'Action', 'Sega', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Rescue your friend from the evil magician.', 'A whimsical and colorful cartoon brawler.', 'Dynamite Dux features Bin the duck as he fights through bizarre worlds. Use power-ups like flamethrowers and bombs to clear out weird enemies in this charming and highly original Sega arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-headdy-brazil', 'Master System', 'Dynamite Headdy (Brazil)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling action platformer.', 'Defeat Dark Demon and save the puppet world.', 'A frantic action game with head-swapping mechanics.', 'Dynamite Headdy is a technical marvel on the Master System. Swap Headdy’s head for different powers and battle massive bosses in this vibrant, high-energy title from the legendary developer Treasure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('e-swat---city-under-siege-usa-europe-easy-version', 'Master System', 'E-SWAT - City Under Siege (USA, Europe) (Easy Version)', '1990', 'Action', 'Sega', '1', 'Sci-Fi', 'Side-scrolling beat ''em up / shooter.', 'Arrest criminals and upgrade to a cybernetic suit.', 'A futuristic police action game.', 'E-SWAT (Easy Version) offers a more accessible entry into the world of Liberty City. Battle criminals on foot before suiting up in high-tech armor to take down a massive criminal syndicate in this sci-fi classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('e-swat---city-under-siege-usa-europe-hard-version', 'Master System', 'E-SWAT - City Under Siege (USA, Europe) (Hard Version)', '1990', 'Action', 'Sega', '1', 'Sci-Fi', 'Side-scrolling beat ''em up / shooter.', 'Arrest criminals and upgrade to a cybernetic suit.', 'A high-difficulty version of the cyber-cop actioner.', 'The Hard Version of E-SWAT provides a brutal challenge for experienced players. Master your weaponry and the specialized cyber-suit to survive some of the most difficult boss fights on the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-brazil', 'Master System', 'Earthworm Jim (Brazil)', '1994', 'Platform', 'Virgin Interactive', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save Princess What''s-Her-Name from Psy-Crow.', 'A zany and technically impressive 8-bit port.', 'Earthworm Jim on the Master System is a rare Brazilian achievement. Despite the hardware limits, it captures the surreal humor and fluid animation of the original, offering a full-featured 8-bit run-and-gun experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco---the-tides-of-time-brazil', 'Master System', 'Ecco - The Tides of Time (Brazil)', '1994', 'Action', 'Sega', '1', 'Nature', 'Side-scrolling adventure.', 'Protect the oceans and travel through time.', 'A beautiful and atmospheric underwater sequel.', 'Ecco: The Tides of Time (Brazil) is a late-release masterpiece. Explore vast oceans and use new transformations in this visually stunning and difficult adventure that pushes the Master System to its absolute limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-the-dolphin-europe', 'Master System', 'Ecco the Dolphin (Europe)', '1992', 'Action', 'Sega', '1', 'Nature', 'Side-scrolling adventure.', 'Rescue your pod from alien invaders.', 'A unique and artistic underwater exploration game.', 'Ecco the Dolphin is one of the most unique games of its era. Navigate complex underwater labyrinths and use sonar to interact with the environment in this beautiful, moody, and notoriously challenging title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('enduro-racer-japan', 'Master System', 'Enduro Racer (Japan)', '1987', 'Racing', 'Sega', '1', 'Arcade', 'Isometric racing and jumping.', 'Win the off-road race across various terrains.', 'The original Japanese version of the bike racer.', 'Enduro Racer (Japan) features a distinct isometric view and RPG elements like bike upgrades. Jump over obstacles and manage your speed to reach the finish line in this highly addictive Sega arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('enduro-racer-usa-europe', 'Master System', 'Enduro Racer (USA, Europe)', '1987', 'Racing', 'Sega', '1', 'Arcade', 'Isometric racing and jumping.', 'Win the off-road race across various terrains.', 'The Western release of the off-road racing hit.', 'Enduro Racer (USA/Europe) delivers high-speed bike action with a focus on timing and jumps. Compete against the clock and other racers in this polished 8-bit port that remains a fan favorite for its tight controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('excellent-dizzy-collection-the-usa-europe-enfrdeesit-proto', 'Master System', 'Excellent Dizzy Collection, The (USA, Europe) (En,Fr,De,Es,It) (Proto)', '1993', 'Compilation', 'Codemasters', '1', 'Cartoon', 'Multi-game puzzle collection.', 'Complete varied tasks across three Dizzy titles.', 'A compilation featuring the famous "egg" hero.', 'The Excellent Dizzy Collection brings three distinct adventures—Go! Dizzy Go!, Dizzy the Adventurer, and Panic Dizzy—to one cartridge. Experience the best of the iconic puzzle series in this rare 8-bit compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-16-fighter-usa-europe', 'Master System', 'F-16 Fighter (USA, Europe)', '1989', 'Simulation', 'Sega', '1', 'Military', 'First-person flight combat.', 'Shoot down enemy MiGs in aerial dogfights.', 'A technical 8-bit flight simulator.', 'F-16 Fighter puts you in the cockpit of the world''s most famous jet. Master the flight controls and radar to track down and eliminate enemy threats in this early but impressive technical showcase for the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-16-fighting-falcon-japan', 'Master System', 'F-16 Fighting Falcon (Japan)', '1989', 'Simulation', 'Sega', '1', 'Military', 'First-person flight combat.', 'Shoot down enemy MiGs in aerial dogfights.', 'The Japanese edition of the F-16 flight sim.', 'Experience the precision of F-16 Fighting Falcon. This Japanese version offers intense cockpit-view combat, requiring tactical movement and careful use of missiles to dominate the skies and complete your mission.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-16-fighting-falcon-usa', 'Master System', 'F-16 Fighting Falcon (USA)', '1989', 'Simulation', 'Sega', '1', 'Military', 'First-person flight combat.', 'Shoot down enemy MiGs in aerial dogfights.', 'North American release of the F-16 simulator.', 'F-16 Fighting Falcon for the USA market delivers a challenging flight simulation experience. Navigate through enemy airspace and engage in high-stakes dogfights using authentic 8-bit flight mechanics and radar systems.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-europe', 'Master System', 'F1 (Europe)', '1993', 'Racing', 'Lankhor', '1', 'Simulation', 'Top-down Formula One racing.', 'Win the F1 World Championship title.', 'A fast-paced, licensed Formula One racer.', 'F1 brings the speed of the Grand Prix to your console. Featuring real tracks and competitive AI, this late-gen racer provides smooth scrolling and precise handling for the ultimate 8-bit driving experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-games-japan', 'Master System', 'Family Games (Japan)', '1987', 'Compilation', 'Sega', '2', 'Various', 'Multi-game puzzle collection.', 'Complete various logic and board game challenges.', 'A Japanese collection of classic parlor games.', 'Family Games (known as Parlour Games elsewhere) includes billiards, darts, and world bingo. It’s a relaxing compilation designed for multiple players to enjoy classic tabletop competition on the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-dizzy-europe-enfrdeesit', 'Master System', 'Fantastic Dizzy (Europe) (En,Fr,De,Es,It)', '1991', 'Platform', 'Codemasters', '1', 'Cartoon', 'Side-scrolling adventure puzzle.', 'Rescue the Yolkfolk and defeat the wizard Zaks.', 'A massive, open-ended adventure starring Dizzy.', 'Fantastic Dizzy is one of the most complex titles on the system. Explore a huge world, manage your inventory, and solve intricate puzzles in this visually stunning 8-bit port of the famous computer series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasy-zone---the-maze-usa-europe', 'Master System', 'Fantasy Zone - The Maze (USA, Europe)', '1987', 'Action', 'Sega', '1', 'Arcade', 'Maze-based action shooter.', 'Collect coins and clear the maze of enemies.', 'A unique spin-off of the Fantasy Zone series.', 'Fantasy Zone: The Maze combines Pac-Man style navigation with the iconic shooting mechanics of Opa-Opa. Navigate through dozens of colorful mazes, upgrading your ship to clear each room of mechanical foes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasy-zone-japan', 'Master System', 'Fantasy Zone (Japan)', '1986', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Destroy the enemy bases and defeat the boss.', 'The original "cute ''em up" arcade masterpiece.', 'Fantasy Zone (Japan) introduces the vibrant world of Opa-Opa. Buy weapons and engines from the shop to customize your ship and take down bizarre, colorful bosses in this foundational Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasy-zone-world-v11-beta', 'Master System', 'Fantasy Zone (World) (v1.1) (Beta)', '1986', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Destroy the enemy bases and defeat the boss.', 'Beta version of the international shooter release.', 'This rare beta version of Fantasy Zone offers a look at the localization process. Experience the same high-energy shooting and shop mechanics that made the franchise a staple of the 8-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasy-zone-world-v12', 'Master System', 'Fantasy Zone (World) (v1.2)', '1986', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Destroy the enemy bases and defeat the boss.', 'The definitive international version of the hit shmup.', 'Fantasy Zone v1.2 is the polished worldwide release. Balance your budget and your firepower to save the solar system in this bright, challenging, and endlessly charming side-scrolling shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasy-zone-ii---opa-opa-no-namida-japan', 'Master System', 'Fantasy Zone II - Opa-Opa no Namida (Japan)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Rescue your father through various dimensions.', 'The Japanese sequel to the legendary shmup.', 'Fantasy Zone II features branching paths and hidden portals. With more levels and more complex shops than the original, it offers a deeper and more vibrant journey for the iconic sentient ship, Opa-Opa.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasy-zone-ii---the-tears-of-opa-opa-usa-europe', 'Master System', 'Fantasy Zone II - The Tears of Opa-Opa (USA, Europe)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Rescue your father through various dimensions.', 'The Western release of the expansive shmup sequel.', 'The Tears of Opa-Opa expands the Fantasy Zone universe with multi-layered stages. Travel through warp zones to find all enemy bases in this masterpiece of 8-bit color and creative level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ferias-frustradas-do-pica-pau-brazil', 'Master System', 'Ferias Frustradas do Pica Pau (Brazil)', '1996', 'Platform', 'Tectoy', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save your family and reach the goal as Pica Pau.', 'A Brazil-exclusive Woody Woodpecker adventure.', 'Férias Frustradas do Pica Pau is a high-quality platformer from Tectoy. Navigate treacherous environments and use your beak to solve puzzles in this rare and colorful title based on the beloved cartoon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-international-soccer-brazil-enespt', 'Master System', 'FIFA International Soccer (Brazil) (En,Es,Pt)', '1994', 'Sports', 'Electronic Arts', '2', 'Simulation', 'Sports simulation.', 'Win the World Cup with your national team.', 'The definitive 8-bit port of the FIFA franchise.', 'FIFA International Soccer brings the global game to the Master System. Featuring an isometric perspective and smooth passing mechanics, it offers the most comprehensive football experience available on 8-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-bubble-bobble-japan', 'Master System', 'Final Bubble Bobble (Japan)', '1988', 'Puzzle', 'Taito', '2', 'Cute', 'Fixed-screen platformer.', 'Clear 100 levels by popping bubbles.', 'The Japanese-exclusive final version of the series.', 'Final Bubble Bobble is a refined take on the arcade classic. With improved secrets and tight gameplay, it’s the ultimate way to experience Bub and Bob’s quest to rescue their girlfriends on the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-&-forget-ii-europe', 'Master System', 'Fire & Forget II (Europe)', '1991', 'Action', 'Titus Interactive', '1', 'Military', 'Isometric vehicular combat.', 'Track down and destroy terrorist convoys.', 'A high-speed combat racer with flying cars.', 'Fire & Forget II puts you in the driver’s seat of the Thunder Master II. Race against the clock and blast enemies in this fast-paced hybrid of a driving game and a vertical shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-&-ice-brazil', 'Master System', 'Fire & Ice (Brazil)', '1993', 'Platform', 'Graftgold', '1', 'Cartoon', 'Side-scrolling platformer.', 'Use ice powers to defeat the heat and save the world.', 'A puzzle-platformer featuring Cool Coyote.', 'Fire & Ice is a charming late-era title. Help the protagonist use his ice breath to freeze enemies and solve environmental puzzles across various themed worlds in this polished and visually appealing game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flash-the-europe', 'Master System', 'Flash, The (Europe)', '1993', 'Action', 'Ocean Software', '1', 'Superhero', 'Side-scrolling action platformer.', 'Stop the Trickster and save Central City.', 'A high-speed superhero action game.', 'The Flash captures the incredible speed of the Scarlet Speedster. Use your momentum to navigate complex levels and defeat bosses in this late-release title known for its impressive sprite work and fluid movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the-europe', 'Master System', 'Flintstones, The (Europe)', '1994', 'Platform', 'Taito', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find the missing items and reach the goal.', 'A prehistoric adventure based on the 1994 movie.', 'The Flintstones brings Fred and Barney to life with detailed 8-bit graphics. Navigate Bedrock and beyond in this charming platformer that captures the humor and aesthetic of the live-action film adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('forgotten-worlds-europe', 'Master System', 'Forgotten Worlds (Europe)', '1988', 'Shooter', 'Capcom', '2', 'Arcade', 'Side-scrolling rail shooter.', 'Defeat the eight evil gods in a post-apocalyptic world.', 'A unique 360-degree shooting arcade port.', 'Forgotten Worlds features a unique control scheme that allows you to fly and rotate your fire. Battle massive bio-mechanical enemies in this visually stunning and technically impressive arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-oshiro-pit-pot-japan', 'Master System', 'Fushigi no Oshiro Pit Pot (Japan)', '1986', 'Action', 'Sega', '1', 'Arcade', 'Top-down puzzle adventure.', 'Save the princess by navigating a crumbling castle.', 'A strategic puzzle game with sliding floor mechanics.', 'Pit Pot (Fushigi no Oshiro) tasks you with hammering floor tiles to trap enemies. It’s a clever, brain-teasing adventure that requires planning and quick reflexes to find the exit and rescue the princess.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('g-loc-air-battle-europe', 'Master System', 'G-LOC Air Battle (Europe)', '1990', 'Shooter', 'Sega', '1', 'Arcade', 'First-person flight combat.', 'Shoot down enemy planes in 3D-style dogfights.', 'High-speed aerial combat based on the arcade hit.', 'G-LOC Air Battle delivers intense, first-person dogfighting. Experience the sensation of flight with rapid scaling graphics and tight controls as you complete various mission objectives across enemy territory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gaegujangi-ggachi-korea-unl', 'Master System', 'Gaegujangi Ggachi (Korea) (Unl)', '1994', 'Platform', 'Unlicensed', '1', 'Cartoon', 'Side-scrolling platformer.', 'Defeat enemies and reach the goal in this anime adventure.', 'A rare Korean platformer based on a popular manhwa.', 'Gaegujangi Ggachi is a unique piece of Korean gaming history. Featuring bright visuals and traditional platforming, it follows the adventures of the iconic character Ggachi in his fight against diverse foes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gain-ground-europe', 'Master System', 'Gain Ground (Europe)', '1988', 'Action', 'Sega', '2', 'Arcade', 'Top-down strategy action.', 'Rescue prisoners and defeat the enemy army.', 'A tactical arcade port with many playable characters.', 'Gain Ground is a masterpiece of strategy and action. Choose from a variety of specialists—each with unique weapons—to clear 50 screens of enemies in this deep and highly replayable Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galactic-protector-japan', 'Master System', 'Galactic Protector (Japan)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Fixed-screen paddle shooter.', 'Protect the planet from incoming space debris.', 'A unique paddle-controlled defensive shooter.', 'Galactic Protector is a Fantasy Zone spin-off that utilizes the paddle controller. Orbit Opa-Opa around the planet to blast asteroids and enemies in this fast-paced and addictive defensive action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaxy-force-europe', 'Master System', 'Galaxy Force (Europe)', '1988', 'Shooter', 'Sega', '1', 'Arcade', 'Pseudo-3D rail shooter.', 'Navigate space tunnels and destroy enemy cores.', 'A technically ambitious port of the 16-bit arcade hit.', 'Galaxy Force pushes the Master System to its limits with scaling sprites and pseudo-3D environments. Fly through asteroid fields and enemy bases in this high-octane sci-fi shooter experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaxy-force-usa', 'Master System', 'Galaxy Force (USA)', '1988', 'Shooter', 'Sega', '1', 'Arcade', 'Pseudo-3D rail shooter.', 'Navigate space tunnels and destroy enemy cores.', 'The North American release of the 3D space shooter.', 'Experience the intensity of Galaxy Force in the USA version. This port captures the cinematic feel of the arcade original, tasking players with managing energy and fire-rate while navigating dangerous space corridors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-box-serie-esportes-radicais-brazil', 'Master System', 'Game Box Serie Esportes Radicais (Brazil)', '1995', 'Compilation', 'Tectoy', '1', 'Various', 'Multi-event sports compilation.', 'Compete in various extreme sports to win.', 'A Brazilian exclusive "Extreme Sports" game box.', 'Game Box Série Esportes Radicais is a specialized collection for the Brazilian market. Enjoy high-speed competition across several extreme sports disciplines in this rare and collectible sports anthology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gangster-town-usa-europe', 'Master System', 'Gangster Town (USA, Europe)', '1988', 'Shooter', 'Sega', '1', 'Arcade', 'Light phaser shooting gallery.', 'Shoot the gangsters and protect the city.', 'A cinematic mob-themed light gun shooter.', 'Gangster Town is one of the best reasons to own a Light Phaser. Blast your way through car chases, saloons, and docks in this fun, interactive shooting game filled with hidden secrets and destructible environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet-europe', 'Master System', 'Gauntlet (Europe)', '1988', 'Action', 'Atari Games', '4', 'Arcade', 'Top-down dungeon crawler.', 'Find the exit of the labyrinth while fighting monsters.', 'The legendary 4-player arcade fantasy classic.', 'Gauntlet on the Master System brings the iconic dungeon-crawling action home. Choose your hero—Warrior, Valkyrie, Wizard, or Elf—and brave endless hordes of monsters in search of treasure and the exit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('george-foremans-ko-boxing-europe', 'Master System', 'George Foreman''s KO Boxing (Europe)', '1992', 'Sports', 'Sims', '2', 'Boxing', 'One-on-one boxing simulation.', 'Knock out opponents to win the heavyweight belt.', 'A hard-hitting boxing game featuring George Foreman.', 'George Foreman''s KO Boxing delivers heavy-hitting 8-bit action. Master your jabs, hooks, and super-punches to climb the rankings and claim the championship title in this competitive sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geraldinho-brazil', 'Master System', 'Geraldinho (Brazil)', '1995', 'Platform', 'Tectoy', '1', 'Cartoon', 'Side-scrolling action platformer.', 'Defeat monsters and explore the haunted house.', 'A Brazilian re-skin of Teddy Boy featuring Geraldinho.', 'Geraldinho is a unique piece of Brazilian gaming history. Based on the popular local comic character, this fast-paced platformer tasks you with clearing rooms of monsters in a colorful, localized adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-house-japan', 'Master System', 'Ghost House (Japan)', '1986', 'Action', 'Sega', '1', 'Horror', 'Side-scrolling exploration action.', 'Collect five keys and defeat the head vampire.', 'A spooky action game set in a haunted mansion.', 'Ghost House (Japan) brings gothic horror to the Master System. Navigate through secret passages and trap-filled rooms to hunt down vampires in this early, atmospheric title that rewards exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-house-usa-europe', 'Master System', 'Ghost House (USA, Europe)', '1986', 'Action', 'Sega', '1', 'Horror', 'Side-scrolling exploration action.', 'Collect five keys and defeat the head vampire.', 'The international release of the haunted house hunt.', 'In Ghost House, you must explore a massive mansion to find hidden keys. Battle bats, mummies, and Dracula himself in this challenging 8-bit action title that features non-linear level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-house-usa-europe-beta', 'Master System', 'Ghost House (USA, Europe) (Beta)', '1986', 'Action', 'Sega', '1', 'Horror', 'Side-scrolling exploration action.', 'Collect five keys and defeat the head vampire.', 'Beta version of the vampire-hunting action game.', 'This Beta version of Ghost House allows players to experience the spooky gameplay with early development tweaks. Master the mansion''s layout and find the keys to defeat the undead in this classic Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghostbusters-usa-europe', 'Master System', 'Ghostbusters (USA, Europe)', '1984', 'Action', 'Sega', '1', 'Movie', 'Top-down driving and action.', 'Capture ghosts and earn enough money to face Gozer.', 'An 8-bit adaptation of the legendary movie franchise.', 'Ghostbusters lets you manage your own ghost-hunting business. Buy equipment, drive the Ecto-1 through the city, and use your proton packs to trap spirits in this strategic and action-packed movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghoulsn-ghosts-usa-europe', 'Master System', 'Ghouls''n Ghosts (USA, Europe)', '1989', 'Action', 'Capcom', '1', 'Arcade', 'Side-scrolling action platformer.', 'Defeat Lucifer and rescue the Princess’s soul.', 'A faithful and challenging port of the Capcom classic.', 'Ghouls''n Ghosts on the Master System is a technical feat. Fight through graveyards and burning villages, upgrade your armor, and face off against terrifying bosses in this notoriously difficult 8-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('global-defense-usa-europe', 'Master System', 'Global Defense (USA, Europe)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Missile-command style shooting.', 'Protect Earth from incoming nuclear missiles.', 'A fast-paced strategic defense shooter.', 'Global Defense (SDI) puts you in control of a satellite defense system. Use the cursor to target and destroy orbital threats and prevent a global catastrophe in this high-tension arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('global-defense-usa-europe-beta', 'Master System', 'Global Defense (USA, Europe) (Beta)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Missile-command style shooting.', 'Protect Earth from incoming nuclear missiles.', 'Beta version of the strategic orbital shooter.', 'Experience the development stages of Global Defense. This Beta version features the same frantic missile-intercepting gameplay, challenging your reflexes to keep the planet safe from nuclear destruction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gokuaku-doumei-dump-matsumoto-japan', 'Master System', 'Gokuaku Doumei Dump Matsumoto (Japan)', '1987', 'Wrestling', 'Sega', '2', 'Arcade', 'Professional wrestling simulation.', 'Win the championship using brutal wrestling moves.', 'A Japanese wrestling game featuring Dump Matsumoto.', 'Gokuaku Doumei Dump Matsumoto (Body Slam) features female professional wrestling. Use power moves and illegal tactics to dominate the ring in this high-energy sports title exclusive to the Japanese market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golden-axe-usa-europe', 'Master System', 'Golden Axe (USA, Europe)', '1989', 'Beat ''em up', 'Sega', '2', 'Arcade', 'Side-scrolling hack and slash.', 'Defeat Death Adder and rescue the King.', 'An iconic fantasy brawler with magic and mounts.', 'Golden Axe brings the legendary arcade brawler to the home console. Choose your hero and use devastating magic spells and rideable beasts to clear the land of Yuria from evil.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golden-axe-warrior-usa-europe', 'Master System', 'Golden Axe Warrior (USA, Europe)', '1991', 'RPG', 'Sega', '1', 'Fantasy', 'Top-down action adventure.', 'Find the nine crystals and defeat Death Adder.', 'A Zelda-style epic set in the Golden Axe universe.', 'Golden Axe Warrior is a deep RPG exploration game. Solve puzzles in complex dungeons and explore a vast overworld to gather the power needed to stop the evil Death Adder in his tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golfamania-europe', 'Master System', 'Golfamania (Europe)', '1990', 'Sports', 'Sanritsu Denki', '2', 'Simulation', 'Sports simulation (Golf).', 'Complete 18 holes with the lowest score.', 'A comprehensive and colorful golf simulator.', 'Golfamania offers a relaxing but deep golf experience. With multiple courses, variable wind conditions, and a focus on timing, it’s the definitive way to hit the links on the Sega Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golfamania-europe-beta', 'Master System', 'Golfamania (Europe) (Beta)', '1990', 'Sports', 'Sanritsu Denki', '2', 'Simulation', 'Sports simulation (Golf).', 'Complete 18 holes with the lowest score.', 'Beta version of the classic 8-bit golf title.', 'This Beta version of Golfamania features the core mechanics of the final release. Practice your swing and master the greens in this early look at one of the system''s most polished sports simulations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golvellius-usa-europe', 'Master System', 'Golvellius (USA, Europe)', '1988', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action RPG.', 'Defeat the demon Golvellius and save the princess.', 'A vibrant and challenging Action-RPG adventure.', 'Golvellius: Valley of Doom features a mix of top-down and side-scrolling exploration. Navigate trap-filled dungeons and upgrade your sword and boots to defeat the seven great demons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gp-rider-europe', 'Master System', 'GP Rider (Europe)', '1990', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back motorcycle racing.', 'Outrace opponents to win the championship.', 'A high-speed arcade-style motorcycle racer.', 'GP Rider brings the thrill of the track to your screen. Featuring a split-screen 2-player mode and smooth scaling graphics, it offers a competitive and fast-paced racing experience for bike enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-baseball-japan', 'Master System', 'Great Baseball (Japan)', '1984', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation (Baseball).', 'Score more runs than the opposing team.', 'The original Japanese version of the baseball sim.', 'Great Baseball (Japan) offers a classic 8-bit take on the diamond sport. Manage your roster and master the timing of pitches and hits to win the league in this early Sega Sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-baseball-usa-europe', 'Master System', 'Great Baseball (USA, Europe)', '1984', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation (Baseball).', 'Score more runs than the opposing team.', 'The international release of the Sega baseball sim.', 'Step up to the plate in Great Baseball. This version features updated teams and refined mechanics, providing a solid and competitive baseball experience for 8-bit sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-basketball-world', 'Master System', 'Great Basketball (World)', '1987', 'Sports', 'Sega', '2', 'Arcade', 'Sports simulation (Basketball).', 'Outscore the opponent in a full-court game.', 'Fast-paced 8-bit basketball action.', 'Great Basketball features international teams and a unique shooting mechanic. Compete in a global tournament and master the art of the 3-pointer in this energetic sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-football-world', 'Master System', 'Great Football (World)', '1987', 'Sports', 'Sega', '2', 'Arcade', 'Sports simulation (Football).', 'Score touchdowns to win the game.', 'American football simulation for the Master System.', 'Great Football offers a strategic take on the gridiron. Call plays from the sidelines and execute passes and runs to lead your team to victory in this early 8-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-golf-japan', 'Master System', 'Great Golf (Japan)', '1984', 'Sports', 'Sega', '1', 'Simulation', 'Sports simulation (Golf).', 'Complete the course with the fewest strokes.', 'The Japanese edition of the Sega golf series.', 'Great Golf (Japan) provides a technical look at the sport. Use the power bar to control your swing and navigate challenging hazards in this foundational entry for Sega’s sports lineup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-golf-world', 'Master System', 'Great Golf (World)', '1984', 'Sports', 'Sega', '1', 'Simulation', 'Sports simulation (Golf).', 'Complete the course with the fewest strokes.', 'The worldwide release of the 8-bit golf sim.', 'Great Golf features a variety of clubs and courses to master. Focus on your aim and power to sink birdies and eagles in this classic sports title that helped define the genre on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-golf-world-beta', 'Master System', 'Great Golf (World) (Beta)', '1984', 'Sports', 'Sega', '1', 'Simulation', 'Sports simulation (Golf).', 'Complete the course with the fewest strokes.', 'Beta version of the worldwide golf release.', 'Explore the early mechanics of Great Golf in this Beta version. Test your skills on the green and manage your club selection to overcome the wind and terrain in this 8-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-ice-hockey-japan-usa', 'Master System', 'Great Ice Hockey (Japan, USA)', '1984', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation (Ice Hockey).', 'Score more goals than the opposing team.', 'A fast and frantic 8-bit ice hockey game.', 'Great Ice Hockey is a Card-format classic for the Master System. Experience the speed of the rink with smooth skating and tactical passing in this competitive international hockey simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-soccer-europe', 'Master System', 'Great Soccer (Europe)', '1987', 'Sports', 'Sega', '2', 'Arcade', 'Sports simulation (Soccer).', 'Win the soccer match against international teams.', 'The European edition of the classic soccer title.', 'Great Soccer brings the world''s favorite sport to life. Control your team with precise passing and shooting mechanics to win the international cup in this early 8-bit football classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-soccer-japan', 'Master System', 'Great Soccer (Japan)', '1987', 'Sports', 'Sega', '2', 'Arcade', 'Sports simulation (Soccer).', 'Win the soccer match against international teams.', 'The original Japanese release of the soccer sim.', 'Experience the roots of Sega soccer with Great Soccer (Japan). This title focuses on team management and fast-paced field play, providing a fun and accessible 8-bit soccer experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-tennis-japan', 'Master System', 'Great Tennis (Japan)', '1984', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation (Tennis).', 'Win sets and matches against computer or friends.', 'A responsive and competitive 8-bit tennis game.', 'Great Tennis features a variety of shot types and surfaces. Master your serve and volley to outmaneuver your opponents in one of the most playable sports titles on the Japanese Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-volleyball-japan', 'Master System', 'Great Volleyball (Japan)', '1984', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation (Volleyball).', 'Score points by grounding the ball on the rival court.', 'The original Japanese version of the volleyball sim.', 'Great Volleyball (Japan) captures the timing and teamwork of the sport. Coordinate your spikes and blocks to defeat international teams in this high-energy 8-bit sports competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-volleyball-usa-europe', 'Master System', 'Great Volleyball (USA, Europe)', '1984', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation (Volleyball).', 'Score points by grounding the ball on the rival court.', 'The international release of the volleyball sim.', 'Take to the court in Great Volleyball. This worldwide version features competitive matches and challenging AI, requiring quick reflexes and strategic play to master the 8-bit court.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('haja-no-fuuin-japan', 'Master System', 'Haja no Fuuin (Japan)', '1987', 'Action', 'Sega', '1', 'Fantasy', 'First-person dungeon crawling RPG.', 'Defeat the dark lord and seal the evil portal.', 'A classic Japanese RPG with a deep story.', 'Haja no Fuuin (The Seal of the Curse) is a pioneering RPG for the Master System. Explore a massive world map and navigate complex first-person dungeons to recover lost artifacts and save the kingdom from ancient darkness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hang-on-europe', 'Master System', 'Hang-On (Europe)', '1985', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back motorcycle racing.', 'Reach checkpoints before the timer expires.', 'The iconic arcade high-speed bike racer.', 'Hang-On brings the legendary Yu Suzuki arcade experience to the home console. Master the curves and manage your speed to beat the clock in this foundational title that defined 8-bit racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hang-on-japan', 'Master System', 'Hang-On (Japan)', '1985', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back motorcycle racing.', 'Reach checkpoints before the timer expires.', 'The original Japanese version of the bike racer.', 'Experience the roots of Sega’s racing legacy with Hang-On (Japan). This version delivers smooth, fast-paced motorcycle action that requires precision and nerves of steel to clear every checkpoint.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hang-on-&-astro-warrior-usa', 'Master System', 'Hang-On & Astro Warrior (USA)', '1986', 'Racing', 'Sega', '1', 'Arcade', 'Racing and vertical shooting.', 'Master both bike racing and space combat.', 'A two-game compilation of Sega arcade hits.', 'This combo cartridge features the high-speed racing of Hang-On alongside the intense vertical shooting of Astro Warrior. It’s a perfect duo of early Sega classics that showcase the system''s variety.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hang-on-&-safari-hunt-usa', 'Master System', 'Hang-On & Safari Hunt (USA)', '1986', 'Shooter', 'Sega', '2', 'Arcade', 'Racing and light gun shooting.', 'Master bike racing and jungle hunting.', 'A dual-game pack featuring Light Phaser action.', 'This classic bundle includes Hang-On and Safari Hunt. Switch between high-speed motorcycle racing and a colorful light gun shooting gallery, offering a complete hardware showcase for the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heavyweight-champ-europe', 'Master System', 'Heavyweight Champ (Europe)', '1991', 'Sports', 'Sega', '2', 'Boxing', 'Side-view boxing combat.', 'Move up the ranks to win the world title.', 'A hard-hitting boxing sim with 2D movement.', 'Heavyweight Champ features a unique side-on perspective for boxing. Dodge, weave, and land powerful punches to knock out your opponents in this challenging and competitive 8-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heroes-of-the-lance-europe', 'Master System', 'Heroes of the Lance (Europe)', '1991', 'Action', 'U.S. Gold', '1', 'Fantasy', 'Side-scrolling action adventure.', 'Lead 8 heroes into the ruins to find the Disks.', 'A Dungeons & Dragons adventure based on the novels.', 'Heroes of the Lance brings the Dragonlance world to the Master System. Control a party of legendary heroes, using their unique abilities to survive the dangerous ruins of Xak Tsaroth and defeat the dragon Khisanth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('high-school!-kimengumi-japan', 'Master System', 'High School! Kimengumi (Japan)', '1988', 'Adventure', 'Sega', '1', 'Comedy', 'Point-and-click adventure.', 'Navigate school life and solve character puzzles.', 'A quirky adventure based on the hit 80s anime.', 'High School! Kimengumi is a charming Japanese adventure game. Guide the eccentric "Funny-face Club" through various school-based scenarios, solving puzzles and interacting with the colorful cast of the manga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('high-school!-kimengumi-japan-en-by-aya+nick-v10', 'Master System', 'High School! Kimengumi (Japan) [En by Aya+Nick v1.0]', '1988', 'Adventure', 'Sega', '1', 'Comedy', 'Point-and-click adventure.', 'Navigate school life and solve character puzzles.', 'English-translated version of the school adventure.', 'This fan-translated version allows Western players to finally enjoy High School! Kimengumi. Experience the humor and unique puzzles of this Japanese classic with fully localized English text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hokuto-no-ken-japan', 'Master System', 'Hokuto no Ken (Japan)', '1987', 'Action', 'Sega', '1', 'Anime', 'Side-scrolling martial arts brawler.', 'Defeat the masters and rescue Yuria.', 'The original Japanese Fist of the North Star.', 'Hokuto no Ken is the brutal foundation for what became Black Belt. Experience Kenshiro''s quest to save his fiancé, featuring iconic martial arts moves and cinematic boss fights that defined the 8-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('home-alone-europe', 'Master System', 'Home Alone (Europe)', '1991', 'Platform', 'Bethesda Softworks', '1', 'Movie', 'Side-scrolling adventure.', 'Protect your house by setting traps for burglars.', 'A strategic action game based on the hit movie.', 'Home Alone tasks you with defending the McCallister house. Use Kevin’s gadgets and traps to stop Harry and Marv from stealing your family''s valuables in this creative movie adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hook-europe-proto', 'Master System', 'Hook (Europe) (Proto)', '1992', 'Action', 'Ocean Software', '1', 'Movie', 'Side-scrolling platformer.', 'Rescue Peter Pan''s children from Captain Hook.', 'Prototype of the action game based on the film.', 'Hook (Proto) offers a rare look at the development of the Neverland adventure. Navigate through forests and pirate ships as Peter Pan in this visually impressive 8-bit cinematic platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-wo-sagasite-japan', 'Master System', 'Hoshi wo Sagasite... (Japan)', '1986', 'Adventure', 'Sega', '1', 'Drama', 'Visual novel/Adventure.', 'Find the missing star and solve the mystery.', 'A Japanese sci-fi adventure with high-quality art.', 'Hoshi wo Sagasite (Searching for the Stars) is a rare narrative-driven title. Navigate through beautifully drawn screens and solve puzzles in this localized version of the Japanese computer classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('impossible-mission-europe', 'Master System', 'Impossible Mission (Europe)', '1988', 'Puzzle', 'Epyx', '1', 'Sci-Fi', 'Platforming and puzzle solving.', 'Find 32 puzzle pieces and stop the robot army.', 'A complex, non-linear stealth and action game.', 'Impossible Mission is a faithful port of the computer classic. Explore the sprawling fortress of Professor Elvin Atombender, avoiding deadly robots and searching for the pieces of the launch code.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-crash-dummies-the-europe', 'Master System', 'Incredible Crash Dummies, The (Europe)', '1993', 'Action', 'Avalanche Software', '1', 'Cartoon', 'Multi-event action simulation.', 'Complete crash tests while minimizing damage.', 'A quirky action game based on the toy line.', 'The Incredible Crash Dummies features unique levels centered around destruction. Guide Bob and Daryl through various hazards and vehicles in this fun and colorful late-generation title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-hulk-the-europe', 'Master System', 'Incredible Hulk, The (Europe)', '1994', 'Action', 'Radical Entertainment', '1', 'Superhero', 'Side-scrolling action platformer.', 'Stop the Leader and his gamma-powered army.', 'A visually massive superhero brawler.', 'The Incredible Hulk is a technical marvel on the Master System. Featuring huge sprites and branching paths, Bruce Banner must navigate through city streets and labs to stop a global catastrophe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-last-crusade-europe', 'Master System', 'Indiana Jones and the Last Crusade (Europe)', '1989', 'Action', 'U.S. Gold', '1', 'Movie', 'Side-scrolling action adventure.', 'Find the Holy Grail and rescue your father.', 'A cinematic quest based on the final film trilogy.', 'Indiana Jones and the Last Crusade features multiple gameplay styles, from platforming to puzzle-solving. Follow the movie''s plot through the catacombs of Venice and the temple of the Grail.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-buster-douglas-knockout-boxing-usa', 'Master System', 'James ''Buster'' Douglas Knockout Boxing (USA)', '1990', 'Sports', 'Electronic Arts', '2', 'Boxing', 'One-on-one boxing simulation.', 'Win the heavyweight championship belt.', 'A hard-hitting boxer featuring the man who beat Tyson.', 'James ''Buster'' Douglas Knockout Boxing offers fast-paced sports action. Use a variety of punches and defensive moves to climb the world rankings in this licensed 8-bit sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-bond-007---the-duel-brazil', 'Master System', 'James Bond 007 - The Duel (Brazil)', '1991', 'Action', 'Domark', '1', 'Spy', 'Side-scrolling action shooter.', 'Infiltrate enemy bases and defeat the syndicate.', 'Brazilian release of the James Bond actioner.', 'James Bond 007: The Duel features Timothy Dalton’s likeness. Use gadgets and weapons to fight through dangerous locations, rescue hostages, and dismantle the villain''s secret plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-bond-007---the-duel-europe', 'Master System', 'James Bond 007 - The Duel (Europe)', '1991', 'Action', 'Domark', '1', 'Spy', 'Side-scrolling action shooter.', 'Infiltrate enemy bases and defeat the syndicate.', 'European release of the spy-themed action game.', 'Master the art of 8-bit espionage in The Duel. This version offers smooth platform-shooting gameplay, tasking James Bond with diffusing bombs and outgunning waves of enemy agents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-pond-2---codename-robocod-europe', 'Master System', 'James Pond 2 - Codename RoboCod (Europe)', '1991', 'Platform', 'Millennium Interactive', '1', 'Cartoon', 'Side-scrolling action platformer.', 'Save the toy factory from the evil Dr. Maybe.', 'A vibrant and fluid "robotic" fish adventure.', 'RoboCod features the iconic stretch-ability of James Pond. Navigate through colorful, toy-themed levels in this late-era masterpiece known for its incredible graphics and creative level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jang-pung-3-korea-unl', 'Master System', 'Jang Pung 3 (Korea) (Unl)', '1992', 'Fighting', 'Unlicensed', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat all opponents to win the tournament.', 'A rare Korean 8-bit brawler.', 'Jang Pung 3 is a late-release Korean exclusive fighting game. Featuring a diverse roster of characters and surprisingly deep mechanics for the hardware, it is a prized piece of the Master System library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jang-pung-ii-korea-unl', 'Master System', 'Jang Pung II (Korea) (Unl)', '1992', 'Fighting', 'Unlicensed', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat all opponents to win the tournament.', 'The second entry in the Korean fighter series.', 'Jang Pung II brings arcade-style fighting to the console. With large sprites and unique special moves, it offers a competitive 1v1 experience that pushed the limits of the Master System''s hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-montana-football-usa-europe', 'Master System', 'Joe Montana Football (USA, Europe)', '1991', 'Sports', 'Sega', '2', 'Football', 'Sports simulation (Football).', 'Lead your team to victory in the playoffs.', 'American football featuring Joe Montana.', 'Joe Montana Football delivers a refined 8-bit gridiron experience. Choose your plays strategically and execute passes and runs with smooth animation and responsive controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-europe', 'Master System', 'Jungle Book, The (Europe)', '1994', 'Platform', 'Virgin Interactive', '1', 'Cartoon', 'Side-scrolling platformer.', 'Reach the village and escape Shere Khan.', 'A beautiful Disney adaptation with jungle action.', 'The Jungle Book features Mowgli in a lush 8-bit world. Collect items and swing through the trees in this visually impressive title that captures the spirit of the animated movie perfectly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-europe', 'Master System', 'Jurassic Park (Europe)', '1993', 'Action', 'Ocean Software', '1', 'Movie', 'Side-scrolling action shooter.', 'Capture dinosaurs and reach the park exit.', 'A dark and atmospheric movie-based shooter.', 'Jurassic Park on the Master System is unique for its focus on shooting mechanics. Navigate through the park''s sectors, tranquilizing dinosaurs and surviving a dangerous prehistoric ecosystem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kenseiden-japan', 'Master System', 'Kenseiden (Japan)', '1987', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action platformer.', 'Defeat the warlock and cleanse Japan of demons.', 'A legendary samurai action game.', 'Kenseiden is a masterpiece of atmosphere and difficulty. Play as Hayato, traveling through different provinces of Japan to master new sword techniques and recover your family''s scrolls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kenseiden-usa-europe', 'Master System', 'Kenseiden (USA, Europe)', '1987', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action platformer.', 'Defeat the warlock and cleanse Japan of demons.', 'International version of the samurai classic.', 'Experience the challenge of Kenseiden. With its non-linear world map and deep combat system, it remains one of the most respected action titles in the entire Sega 8-bit library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kings-quest---quest-for-the-crown-usa', 'Master System', 'King''s Quest - Quest for the Crown (USA)', '1989', 'Adventure', 'Sierra On-Line', '1', 'Fantasy', 'Point-and-click adventure.', 'Find the three lost treasures of Daventry.', 'An 8-bit port of the legendary Sierra adventure.', 'King''s Quest brings Sir Graham''s quest to the Master System. Solve logic puzzles and interact with fairy-tale characters in this pioneering adventure game that defined the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kings-quest---quest-for-the-crown-usa-beta', 'Master System', 'King''s Quest - Quest for the Crown (USA) (Beta)', '1989', 'Adventure', 'Sierra On-Line', '1', 'Fantasy', 'Point-and-click adventure.', 'Find the three lost treasures of Daventry.', 'Beta version of the fantasy adventure port.', 'This Beta version of King''s Quest: Quest for the Crown allows players to explore early builds of Graham''s adventure. Navigate the kingdom of Daventry and solve puzzles in this rare piece of software.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klax-europe', 'Master System', 'Klax (Europe)', '1990', 'Puzzle', 'Tengen', '2', 'Abstract', 'Falling tile puzzle.', 'Catch and arrange colored tiles into rows.', 'A fast-paced arcade puzzle game.', 'Klax for the Sega Master System is a frantic and addictive puzzle classic. Catch falling colored tiles on your paddle and drop them into the bin to create horizontal, vertical, or diagonal lines in this perfect 8-bit arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knuckles-in-sonic-the-hedgehog', 'Master System', 'Knuckles in Sonic The Hedgehog', '1996', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Finish levels as fast as possible.', 'A fan-made hack featuring Knuckles in Sonic 1.', 'Knuckles in Sonic the Hedgehog allows you to play the original 8-bit Sonic adventure with a custom Knuckles sprite. Experience the classic zones of South Island with the iconic red echidna in this creative community modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krustys-fun-house-europe', 'Master System', 'Krusty''s Fun House (Europe)', '1992', 'Platform', 'Audiogenic', '1', 'Cartoon', 'Puzzle-solving platformer.', 'Lead all the rats into the trap machines.', 'A brain-teasing puzzle game starring Krusty the Clown.', 'Krusty''s Fun House is a clever and challenging puzzle-platformer. Help Krusty navigate complex levels filled with traps and obstacles to clear his house of a rat infestation in this vibrant and humorous Simpsons spin-off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kujaku-ou-japan', 'Master System', 'Kujaku Ou (Japan)', '1988', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action adventure.', 'Exorcise demons and defeat the dark king.', 'The Japanese version of the SpellCaster series.', 'Kujaku Ou (Peacock King) is an atmospheric blend of action and menu-based adventure. Based on the popular manga, battle ancient Japanese demons and explore mystical shrines in this deep and challenging 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-kid-usa-europe', 'Master System', 'Kung Fu Kid (USA, Europe)', '1988', 'Action', 'Sega', '2', 'Martial Arts', 'Side-scrolling beat ''em up.', 'Defeat the evil Madman and his minions.', 'Fast-paced martial arts action in ancient China.', 'Kung Fu Kid delivers rapid-fire combat and impressive agility. Use your wall-jumping skills and precise strikes to battle through a gauntlet of supernatural foes in this early and highly responsive Master System classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('land-of-illusion-starring-mickey-mouse-europe', 'Master System', 'Land of Illusion Starring Mickey Mouse (Europe)', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Recover the magical beans and save the land.', 'The critically acclaimed sequel to Castle of Illusion.', 'Land of Illusion Starring Mickey Mouse is a visual masterpiece. Explore a vast fairytale world with branching paths and new abilities in this polished adventure that many consider the best platformer on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('laser-ghost-europe', 'Master System', 'Laser Ghost (Europe)', '1991', 'Shooter', 'Sims', '1', 'Arcade', 'Light phaser rail shooter.', 'Protect a young girl''s soul from ghosts.', 'A horror-themed light gun shooter.', 'Laser Ghost is a high-stakes shooting gallery compatible with the Light Phaser. Blast through hordes of ghouls and demonic entities to protect a helpless girl in this atmospheric and intense arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-illusion-starring-mickey-mouse-brazil', 'Master System', 'Legend of Illusion Starring Mickey Mouse (Brazil)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find the legendary crown and save the kingdom.', 'Mickey''s final 8-bit adventure, released in Brazil.', 'Legend of Illusion Starring Mickey Mouse features stunning late-gen graphics. Navigate through a beautiful medieval world using soap bubbles to defeat enemies in this rare and charming chapter of the Illusion series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-europe', 'Master System', 'Lemmings (Europe)', '1991', 'Puzzle', 'DMA Design', '1', 'Strategy', 'Lemmings-management puzzle.', 'Guide a specific number of creatures to the exit.', 'A perfect 8-bit port of the legendary puzzle game.', 'Lemmings on the Master System brings the iconic green-haired creatures home. Assign jobs like digging, climbing, and building to navigate through 100 levels of lethal traps and brain-teasing obstacles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-europe-beta', 'Master System', 'Lemmings (Europe) (Beta)', '1991', 'Puzzle', 'DMA Design', '1', 'Strategy', 'Lemmings-management puzzle.', 'Guide a specific number of creatures to the exit.', 'Beta version of the classic puzzle management game.', 'This Beta version of Lemmings offers a look into the development of the 8-bit port. Test your strategic thinking as you guide your colony to safety across various hazardous environments in this early build.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('line-of-fire-europe', 'Master System', 'Line of Fire (Europe)', '1991', 'Shooter', 'U.S. Gold', '1', 'Arcade', 'Pseudo-3D rail shooter.', 'Rescue the President and escape the enemy base.', 'A fast-paced military shooter with scaling graphics.', 'Line of Fire delivers intense arcade action. Pilot through enemy territory, using your machine gun and missiles to take down vehicles and installations in this technically impressive 8-bit shooting experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-the-europe', 'Master System', 'Lion King, The (Europe)', '1994', 'Platform', 'Westwood Studios', '1', 'Cartoon', 'Side-scrolling platformer.', 'Defeat Scar and take your place as King.', 'A cinematic 8-bit adaptation of the Disney hit.', 'The Lion King features vibrant graphics and a memorable soundtrack. Play as Simba as he grows from a cub to an adult, navigating the Pride Lands and the Elephant Graveyard in this late-release masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lord-of-sword-japan', 'Master System', 'Lord of Sword (Japan)', '1988', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action platformer.', 'Defeat the dark forces and restore the light.', 'The original Japanese version of Lord of the Sword.', 'Lord of Sword is a challenging fantasy action game. Travel across a non-linear world map, choosing your path through forests and castles as you master the art of the blade to defeat ancient evils.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lord-of-the-sword-usa-europe', 'Master System', 'Lord of the Sword (USA, Europe)', '1988', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action platformer.', 'Defeat the dark forces and restore the light.', 'A deep and difficult fantasy action adventure.', 'Lord of the Sword tasks you with proving your worth as the hero of the land. Battle mythical creatures and navigate treacherous terrain in this atmospheric title that blends action with world-building elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('loretta-no-shouzou-japan', 'Master System', 'Loretta no Shouzou (Japan)', '1986', 'Adventure', 'Sega', '1', 'Drama', 'Point-and-click adventure.', 'Solve the mystery of the family portrait.', 'A detective adventure game with anime-style art.', 'Loretta no Shouzou (The Portrait of Loretta) is a Japanese-exclusive mystery. Investigate scenes, collect clues, and interrogate suspects to solve a complex case in this beautifully drawn narrative-driven experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lucky-dime-caper-starring-donald-duck-the-europe', 'Master System', 'Lucky Dime Caper Starring Donald Duck, The (Europe)', '1991', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Huey, Dewey, and Louie from Magica De Spell.', 'A globe-trotting Disney adventure starring Donald.', 'The Lucky Dime Caper is a standout platformer. Choose your route through diverse locations like Egypt and the South Pole, using your mallet and frisbee to defeat enemies and reclaim Scrooge''s lucky dime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lucky-dime-caper-starring-donald-duck-the-europe-beta', 'Master System', 'Lucky Dime Caper Starring Donald Duck, The (Europe) (Beta)', '1991', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Huey, Dewey, and Louie from Magica De Spell.', 'Beta version of Donald Duck''s 8-bit adventure.', 'Experience an early version of The Lucky Dime Caper. This Beta build showcases the fluid controls and creative level design that made the final release a fan favorite for Sega Master System owners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-sengoku-jidai-japan', 'Master System', 'Mahjong Sengoku Jidai (Japan)', '1988', 'Mahjong', 'Sega', '2', 'Board', 'Board game simulation (Mahjong).', 'Win the tournament during the Warring States period.', 'A historical themed Mahjong game from Japan.', 'Mahjong Sengoku Jidai combines classic gameplay with a feudal Japanese setting. Compete against historical figures and master the tiles in this strategic and culturally rich 8-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-sengoku-jidai-japan-beta', 'Master System', 'Mahjong Sengoku Jidai (Japan) (Beta)', '1988', 'Mahjong', 'Sega', '2', 'Board', 'Board game simulation (Mahjong).', 'Win the tournament during the Warring States period.', 'Beta version of the feudal Japanese Mahjong game.', 'This Beta version of Mahjong Sengoku Jidai allows players to test the mechanics of the tile-matching simulation. Experience the strategic depth of Mahjong set against a backdrop of ancient Japanese warfare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('makai-retsuden-japan', 'Master System', 'Makai Retsuden (Japan)', '1988', 'Action', 'Sega', '1', 'Horror', 'Side-scrolling martial arts brawler.', 'Defeat the masters and rescue the princess.', 'The original Japanese version of Black Belt.', 'Makai Retsuden is the Japanese original of the game Black Belt. Based on the Hokuto no Ken (Fist of the North Star) anime, it features intense combat and cinematic boss battles that pushed the 8-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maou-golvellius-japan', 'Master System', 'Maou Golvellius (Japan)', '1987', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action RPG.', 'Defeat the demon Golvellius and save the princess.', 'The original Japanese version of the RPG classic.', 'Maou Golvellius is a vibrant and challenging adventure. Explore the Valley of Doom, battle through top-down and side-scrolling dungeons, and upgrade your gear to stop the ultimate evil in this Sega staple.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marble-madness-europe', 'Master System', 'Marble Madness (Europe)', '1988', 'Puzzle', 'Atari Games', '2', 'Arcade', 'Isometric ball-rolling puzzle.', 'Reach the goal before the timer runs out.', 'A faithful port of the unique arcade physics game.', 'Marble Madness on the Master System is an impressive conversion. Navigate your marble through surreal, obstacle-filled courses while battling gravity and enemies in this classic test of reflexes and precision.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marksman-shooting-&-trap-shooting-usa', 'Master System', 'Marksman Shooting & Trap Shooting (USA)', '1987', 'Sports', 'Sega', '2', 'Shooting', 'Light phaser shooting gallery.', 'Achieve the high score in target and trap shooting.', 'A two-game pack designed for the Light Phaser.', 'Marksman Shooting & Trap Shooting offers a variety of range-based challenges. Test your aim and reaction time in these competitive arcade-style events that showcase the accuracy of the Master System gun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marksman-shooting-&-trap-shooting-&-safari-hunt-europe', 'Master System', 'Marksman Shooting & Trap Shooting & Safari Hunt (Europe)', '1987', 'Sports', 'Sega', '2', 'Shooting', 'Light phaser shooting gallery.', 'Clear the range and survive the jungle safari.', 'A three-game compilation for the Light Phaser.', 'This European exclusive bundle brings together Marksman Shooting, Trap Shooting, and Safari Hunt. It provides the ultimate light gun experience, offering everything from competitive targets to hunting wild animals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('martlets-fun-adventure!-demo', 'Master System', 'Martlet''s Fun Adventure! Demo', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Tech demo/Platformer.', 'Navigate the test environment and reach the end.', 'A modern homebrew demo for the Master System.', 'Martlet''s Fun Adventure! Demo is a showcase of what modern developers can do with 8-bit hardware. Experience smooth scrolling and creative mechanics in this impressive community-driven technical demonstration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('master-of-darkness-europe', 'Master System', 'Master of Darkness (Europe)', '1992', 'Action', 'Sims', '1', 'Horror', 'Side-scrolling action platformer.', 'Stop Count Dracula and his army of the undead.', 'A dark action game similar to Castlevania.', 'Master of Darkness is a Victorian-era masterpiece. Play as Dr. Social as you battle through London’s fog and gothic castles, using a variety of weapons to hunt down the king of vampires in this atmospheric title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('masters-of-combat-europe', 'Master System', 'Masters of Combat (Europe)', '1993', 'Fighting', 'Sims', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat all rivals to become the grand champion.', 'A late-release 1v1 fighter with large sprites.', 'Masters of Combat is one of the best fighting games on the system. Featuring a diverse roster of fighters with unique special moves, it offers a surprisingly deep and fluid combat experience for the hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maze-hunter-3-d-usa-europe', 'Master System', 'Maze Hunter 3-D (USA, Europe)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'First-person 3D maze navigator.', 'Find the exit of the labyrinth and defeat the boss.', 'A unique 3D maze crawler for Sega''s 3D Glasses.', 'Maze Hunter 3-D uses the Master System''s 3D capabilities to create a sense of depth. Navigate through complex mazes from a top-down perspective, using the "pop-out" effect to better judge distances and enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maze-walker-japan', 'Master System', 'Maze Walker (Japan)', '1986', 'Puzzle', 'Sega', '1', 'Abstract', 'Top-down maze navigator.', 'Collect items and find the exit of each level.', 'The Japanese version of the 3D maze game.', 'Maze Walker (known as Maze Hunter 3-D elsewhere) is a challenging test of direction and reflexes. Explore dozens of levels filled with power-ups and monsters in this innovative use of the console''s 3D technology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megumi-rescue-japan', 'Master System', 'Megumi Rescue (Japan)', '1988', 'Action', 'Sega', '1', 'Rescue', 'Vertical rescue simulation.', 'Put out fires and rescue civilians from buildings.', 'A unique paddle-controller rescue game.', 'Megumi Rescue is a rare Japanese gem. Use a trampoline-like mechanic to bounce firefighters up the side of burning buildings to save people, offering a frantic and original take on the rescue genre.');